'use client';

import { cn } from '@/lib/utils';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { isUnlimited, type UsageLevel, usageLevel, usageRatio } from '@/components/ui/billing-kit/format';

const FILL: Record<UsageLevel, string> = {
	ok: 'bg-foreground/55',
	warning: 'bg-warning',
	exhausted: 'bg-destructive',
	over: 'bg-destructive',
};

type AllowanceBarProps = {
	used: number;
	/** `-1` means unlimited. */
	limit: number;
	/** Accessible name, e.g. "Read operations". */
	label: string;
	/** Share at which the bar turns amber. Defaults to 0.8. */
	soft?: number;
	/** Where the plan's own allowance ends inside `limit`; credits fill the rest. */
	planMarker?: number;
	size?: 'sm' | 'md';
	className?: string;
};

/**
 * A meter bar: neutral while comfortable, amber past the soft threshold, red
 * when exhausted. A tick marks where the plan allowance ends and purchased
 * credits begin. Unlimited allowances render as an empty dashed track.
 */
export function AllowanceBar({ used: usedProp, limit, label, soft = 0.8, planMarker, size = 'md', className }: AllowanceBarProps) {
	const f = useBillingFormat();
	// A negative count (a correction larger than what was used) is an empty bar, not an invalid width.
	const used = Math.max(0, usedProp);
	const unlimited = isUnlimited(limit);
	const ratio = usageRatio(used, limit) ?? 0;
	const level = usageLevel(used, limit, soft);
	const height = size === 'sm' ? 'h-1' : 'h-1.5';
	if (unlimited) {
		return (
			<div
				role="img"
				aria-label={`${label}: unlimited`}
				className={cn('w-full rounded-full border border-dashed border-foreground/15', height, className)}
			/>
		);
	}
	const markerAt = planMarker !== undefined && limit > 0 && planMarker > 0 && planMarker < limit ? planMarker / limit : null;
	return (
		<div
			role="meter"
			aria-label={label}
			aria-valuemin={0}
			aria-valuemax={limit}
			aria-valuenow={Math.min(used, limit)}
			aria-valuetext={`${f.quantity(used)} of ${f.quantity(limit)}`}
			className={cn('relative w-full overflow-hidden rounded-full bg-foreground/[0.07]', height, className)}
		>
			<div
				className={cn('h-full rounded-full transition-[width] duration-(--duration-slow) ease-out motion-reduce:transition-none', FILL[level])}
				style={{ width: `${Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 1)) * 100}%` }}
			/>
			{markerAt !== null ? (
				<span aria-hidden="true" className="absolute inset-y-0 w-px bg-background" style={{ insetInlineStart: `${markerAt * 100}%` }} />
			) : null}
		</div>
	);
}

type UsageFigureProps = {
	used: number;
	limit: number;
	unit: string;
	compact?: boolean;
	className?: string;
};

/** "4.2M / 10M operations", "12 / unlimited seats", with the used figure emphasised. */
export function UsageFigure({ used, limit, unit, compact = true, className }: UsageFigureProps) {
	const f = useBillingFormat();
	return (
		<span className={cn('text-[0.8125rem] tabular-nums [overflow-wrap:anywhere]', className)}>
			<span className="whitespace-nowrap">
				<span className="font-medium text-foreground">{f.quantity(used, compact)}</span>
				<span className="text-muted-foreground">
					{' / '}
					{isUnlimited(limit) ? 'unlimited' : f.quantity(limit, compact)}
				</span>
			</span>
			<span className="text-muted-foreground"> {unit}</span>
		</span>
	);
}

type SparklineProps = {
	values: number[];
	label: string;
	/** Days still to come in the period, drawn as faint placeholders. */
	remaining?: number;
	className?: string;
};

/** Daily bars for the period so far; the latest day is emphasised. */
export function Sparkline({ values, label, remaining = 0, className }: SparklineProps) {
	const max = Math.max(1, ...values);
	const total = values.length + remaining;
	return (
		<div role="img" aria-label={label} className={cn('flex h-8 items-end gap-[2px]', className)}>
			{values.map((value, index) => (
				<span
					key={index}
					className={cn('min-w-[2px] flex-1 rounded-[2px]', index === values.length - 1 ? 'bg-foreground/60' : 'bg-foreground/20')}
					style={{ height: `${Math.max(6, (value / max) * 100)}%` }}
				/>
			))}
			{Array.from({ length: remaining }, (_, index) => (
				<span key={`r${index}`} className="h-[6%] min-w-[2px] flex-1 rounded-[2px] bg-foreground/[0.06]" />
			))}
			<span className="sr-only">{`${values.length} of ${total} days`}</span>
		</div>
	);
}

const DAY_MS = 86_400_000;

type PeriodTrackProps = {
	start: string;
	end: string;
	/** Defaults to the formatter's clock. */
	now?: string;
	/** `warning` tints today's tick, e.g. while a payment is overdue. */
	tone?: 'default' | 'warning';
	className?: string;
};

/**
 * The billing period as a thin segmented bar: one segment per day (per week
 * for yearly periods). Days behind are filled, today glows in colour, and the
 * days left stay quiet.
 */
export function PeriodTrack({ start, end, now: nowProp, tone = 'default', className }: PeriodTrackProps) {
	const f = useBillingFormat();
	const from = new Date(start).getTime();
	const to = new Date(end).getTime();
	const now = new Date(nowProp ?? f.now).getTime();
	const days = Math.max(1, Math.round((to - from) / DAY_MS));
	const weekly = days > 62;
	const unit = weekly ? DAY_MS * 7 : DAY_MS;
	const count = Math.max(1, Math.ceil((to - from) / unit));
	const elapsed = Math.min(count, Math.max(0, Math.floor((now - from) / unit)));
	const today = elapsed < count ? elapsed : -1;
	const color = tone === 'warning' ? 'var(--warning)' : 'var(--primary)';
	const dayOfPeriod = Math.min(days, Math.max(1, Math.floor((now - from) / DAY_MS) + 1));

	return (
		<div
			role="meter"
			aria-label="Billing period"
			aria-valuemin={1}
			aria-valuemax={days}
			aria-valuenow={dayOfPeriod}
			aria-valuetext={`Day ${dayOfPeriod} of ${days}, ends ${f.date(end)}`}
			className={cn('flex h-1 gap-[2px]', className)}
		>
			{Array.from({ length: count }, (_, index) => {
				const isToday = index === today;
				return (
					<span
						key={index}
						aria-hidden="true"
						className={cn(
							'min-w-px flex-1 rounded-full transition-[background-color] duration-(--duration-slow) ease-out motion-reduce:transition-none',
							isToday ? null : index < elapsed ? 'bg-foreground/45' : 'bg-foreground/[0.12]',
						)}
						style={isToday ? { backgroundColor: color, boxShadow: `0 0 6px color-mix(in oklab, ${color} 55%, transparent)` } : undefined}
					/>
				);
			})}
		</div>
	);
}

'use client';

import { Infinity as InfinityIcon, Lock, Plus } from 'lucide-react';
import * as React from 'react';

import { plural } from '@/lib/intl';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { focusRingClass, ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { humanize, INTERVAL_LABEL, isUnlimited } from '@/components/ui/billing-kit/format';
import type { EntitlementRow } from '@/components/ui/billing-kit/plan';
import { type BillingProviderDescriptor } from '@/components/ui/billing-kit/providers';
import { ExternalRef, SyncBadge } from '@/components/ui/billing-kit/provider';
import { TableSurface, tableGroupRowClass, tableHeadClass, tableRowClass } from '@/components/ui/billing-kit/surface';
import type { CreditPack, Meter, Plan, PlanPrice, ProviderMode } from '@/components/ui/billing-kit/types';

/** The switch box is its own 18px track now (the touch target is a pseudo-element), so it only needs to centre on the row's text. */
const tableSwitchClass = 'align-middle';

/* ------------------------------------------------------------------ *
 * Entitlement matrix
 * ------------------------------------------------------------------ */

export type EntitlementGroup = { title: string; rows: EntitlementRow[] };

type EntitlementMatrixProps = {
	plans: Plan[];
	groups: EntitlementGroup[];
	/** When set, cells become editable and report every change. */
	onChange?: (planId: string, row: EntitlementRow, value: number) => void;
	/** Cells that differ from the saved catalog, keyed `planId:kind:key`. */
	dirty?: ReadonlySet<string>;
	className?: string;
};

export const entitlementKey = (planId: string, row: Pick<EntitlementRow, 'kind' | 'key'>) => `${planId}:${row.kind}:${row.key}`;

function readValue(plan: Plan, row: EntitlementRow) {
	return (row.kind === 'limit' ? plan.limits : row.kind === 'meter' ? plan.meterLimits : plan.caps)[row.key];
}

function MatrixCell({ plan, row, numeric, onChange, dirty }: { plan: Plan; row: EntitlementRow; numeric: boolean; onChange?: EntitlementMatrixProps['onChange']; dirty: boolean }) {
	const f = useBillingFormat();
	const value = readValue(plan, row);
	const label = `${row.label} for ${plan.displayName}`;
	const [draft, setDraft] = React.useState<string | null>(null);

	if (row.kind === 'cap' && !numeric) {
		return onChange ? (
			<Switch className={tableSwitchClass} aria-label={label} checked={(value ?? 0) > 0} onCheckedChange={(checked) => onChange(plan.id, row, checked ? 1 : 0)} />
		) : (
			<span className="text-foreground">{(value ?? 0) > 0 ? 'On' : <span className="text-subtle-foreground">Off</span>}</span>
		);
	}

	const shown = value === undefined ? '—' : isUnlimited(value) ? '∞' : f.limit(value);
	if (!onChange) {
		return (
			<span
				title={value !== undefined && !isUnlimited(value) && shown !== f.quantity(value) ? f.quantity(value) : undefined}
				className={cn('tabular-nums', value === undefined ? 'text-subtle-foreground' : 'text-foreground')}
			>
				{shown}
			</span>
		);
	}
	const formatted = value === undefined ? '' : isUnlimited(value) ? '∞' : f.quantity(value);
	const text = draft ?? formatted;

	const commit = () => {
		if (draft === null) return;
		const trimmed = draft.trim().toLowerCase();
		const next = trimmed === '' || trimmed === '∞' || trimmed === 'unlimited' ? -1 : Number(trimmed.replace(/[, _]/g, ''));
		if (Number.isFinite(next) && next >= -1) onChange(plan.id, row, Math.round(next));
		setDraft(null);
	};

	return (
		<span className="flex items-center justify-end gap-1">
			<input
				aria-label={label}
				inputMode="numeric"
				value={text}
				placeholder="—"
				onFocus={(event) => {
					setDraft(value === undefined ? '' : isUnlimited(value) ? '∞' : String(value));
					const input = event.currentTarget;
					requestAnimationFrame(() => input.select());
				}}
				onChange={(event) => setDraft(event.target.value)}
				onBlur={commit}
				onKeyDown={(event) => {
					if (event.key === 'Enter') event.currentTarget.blur();
					if (event.key === 'Escape') {
						setDraft(null);
						event.currentTarget.blur();
					}
				}}
				style={{ width: `${Math.max(formatted.length, text.length, 1) + 3}ch` }}
				className={cn(
					'h-7 min-w-24 rounded-md border bg-transparent px-2 text-end text-[0.8125rem] tabular-nums outline-none',
					'border-transparent hover:border-border focus:border-border focus:bg-card focus:ring-[3px] focus:ring-ring/50',
					dirty && 'border-primary/30 bg-primary/[0.06]',
				)}
			/>
			<Tooltip>
				<TooltipTrigger
					render={
						<button
							type="button"
							aria-label={`Make ${label} unlimited`}
							aria-pressed={value !== undefined && isUnlimited(value)}
							onClick={() => onChange(plan.id, row, value !== undefined && isUnlimited(value) ? 0 : -1)}
							className={cn(
								'grid size-6 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground hover:bg-overlay-hover hover:text-foreground aria-pressed:text-primary',
								focusRingClass,
							)}
						>
							<InfinityIcon aria-hidden="true" className="size-3.5" />
						</button>
					}
				/>
				<TooltipContent>Unlimited</TooltipContent>
			</Tooltip>
		</span>
	);
}

/**
 * Plans across, entitlements down: counted limits, meter allowances, and
 * feature caps, grouped. Numbers edit in place (type `∞` or use the toggle for
 * unlimited); caps are switches. Saving is the host's job: this reports each
 * change and highlights the cells passed in `dirty`.
 */
export function EntitlementMatrix({ plans, groups, onChange, dirty, className }: EntitlementMatrixProps) {
	return (
		<TableSurface className={className} minWidth={`${14 + plans.length * 9}rem`}>
			<thead className={tableHeadClass}>
				<tr>
					<th scope="col" className="sticky start-0 z-10 w-56 bg-[color-mix(in_oklab,var(--muted)_60%,var(--card))]">
						Entitlement
					</th>
					{plans.map((plan) => (
						<th key={plan.id} scope="col" className="text-end">
							<span className="text-foreground">{plan.displayName}</span>
						</th>
					))}
				</tr>
			</thead>
			{groups.map((group) => (
				<tbody key={group.title}>
					<tr className={tableGroupRowClass}>
						<th scope="rowgroup" colSpan={plans.length + 1}>
							{group.title}
						</th>
					</tr>
					{group.rows.map((row) => (
						<tr key={`${row.kind}:${row.key}`} className={tableRowClass}>
							<th scope="row" className="sticky start-0 z-10 bg-card px-4 py-2 text-start font-normal">
								<span className="block text-foreground [overflow-wrap:anywhere]">{row.label}</span>
								<span className="block font-mono text-[0.6875rem] text-subtle-foreground [overflow-wrap:anywhere]">{row.key}</span>
							</th>
							{plans.map((plan) => (
								<td key={plan.id} className="text-end">
									<MatrixCell
										plan={plan}
										row={row}
										numeric={row.kind !== 'cap' || plans.some((candidate) => (readValue(candidate, row) ?? 0) > 1 || isUnlimited(readValue(candidate, row) ?? 0))}
										onChange={onChange}
										dirty={Boolean(dirty?.has(entitlementKey(plan.id, row)))}
									/>
								</td>
							))}
						</tr>
					))}
				</tbody>
			))}
		</TableSurface>
	);
}

/* ------------------------------------------------------------------ *
 * Plans and prices
 * ------------------------------------------------------------------ */

type PlanPriceTableProps = {
	plans: Plan[];
	provider?: BillingProviderDescriptor;
	mode?: ProviderMode;
	/** Subscriber count per plan id. */
	subscribers?: Record<string, number>;
	onTogglePlan?: (plan: Plan, active: boolean) => void;
	onTogglePrice?: (plan: Plan, price: PlanPrice, active: boolean) => void;
	onAddPrice?: (plan: Plan) => void;
	className?: string;
};

/**
 * Every plan with its prices and how each mirrors to the provider. Prices are
 * immutable once they exist, so a new amount is a new row and old rows are
 * retired, never edited.
 */
export function PlanPriceTable({ plans, provider, mode = 'live', subscribers, onTogglePlan, onTogglePrice, onAddPrice, className }: PlanPriceTableProps) {
	const f = useBillingFormat();
	return (
		<TableSurface className={className} minWidth="48rem">
			<caption className="sr-only">Billing plans and provider prices.</caption>
			<thead className={tableHeadClass}>
				<tr>
					<th scope="col">Plan / price</th>
					<th scope="col">Billing</th>
					<th scope="col" className="text-end">
						Amount
					</th>
					<th scope="col">Provider</th>
					<th scope="col" className="text-end">
						Active
					</th>
				</tr>
			</thead>
			{plans.map((plan) => (
				<tbody key={plan.id}>
					<tr className="border-t border-border bg-muted/30 [&_td]:px-4 [&_td]:py-2">
						<td colSpan={2}>
							<span className="flex flex-wrap items-center gap-2">
								<span className="min-w-0 font-medium text-foreground [overflow-wrap:anywhere]">{plan.displayName}</span>
								<span className="min-w-0 font-mono text-[0.6875rem] text-subtle-foreground [overflow-wrap:anywhere]">{plan.name}</span>
								{plan.fallback ? <ToneBadge tone="neutral">Free fallback</ToneBadge> : null}
								{subscribers?.[plan.id] !== undefined ? (
									<span className="text-xs text-muted-foreground tabular-nums">
										{f.quantity(subscribers[plan.id]!)} {plural(subscribers[plan.id]!, { one: 'subscriber', other: 'subscribers' })}
									</span>
								) : null}
							</span>
						</td>
						<td className="text-end">
							{onAddPrice ? (
								<Button size="xs" variant="ghost" onClick={() => onAddPrice(plan)}>
									<Plus aria-hidden="true" />
									Price
								</Button>
							) : null}
						</td>
						<td>
							<span className="flex flex-wrap items-center gap-2">
								{plan.syncState ? <SyncBadge state={plan.syncState} /> : null}
								{plan.externalId ? <ExternalRef provider={provider} kind="product" id={plan.externalId} mode={mode} /> : null}
							</span>
						</td>
						<td className="text-end">
							<Switch
								className={tableSwitchClass}
								aria-label={`${plan.active ? 'Retire' : 'Offer'} ${plan.displayName}`}
								checked={plan.active}
								disabled={!onTogglePlan}
								onCheckedChange={(active) => onTogglePlan?.(plan, active)}
							/>
						</td>
					</tr>
					{plan.prices.map((price) => (
						<tr key={price.id} className={cn(tableRowClass, !price.active && 'text-muted-foreground')}>
							<td className="ps-9!">
								<span className="flex items-center gap-2">
									<span className={price.active ? 'text-foreground' : undefined}>{INTERVAL_LABEL[price.interval]}</span>
									{price.discountPercent ? <ToneBadge tone="success">−{price.discountPercent}%</ToneBadge> : null}
								</span>
							</td>
							<td>
								<ToneBadge tone={price.usageType === 'metered' ? 'violet' : 'neutral'}>{price.usageType === 'metered' ? 'Usage (credits)' : 'Flat'}</ToneBadge>
							</td>
							<td className="text-end tabular-nums">
								{price.usageType === 'metered' ? (
									<Tooltip>
										<TooltipTrigger render={<span className="inline-flex items-center gap-1 text-muted-foreground" tabIndex={0} />}>
											<Lock aria-hidden="true" className="size-3" />
											Per credit
										</TooltipTrigger>
										<TooltipContent>Charged at the database credit rate, so the row itself carries 0.</TooltipContent>
									</Tooltip>
								) : (
									<span className={price.active ? 'font-medium text-foreground' : undefined}>{f.money(price.amount, { precise: true })}</span>
								)}
							</td>
							<td>
								<span className="flex flex-wrap items-center gap-2">
									{price.syncState ? <SyncBadge state={price.syncState} /> : null}
									{price.externalId ? <ExternalRef provider={provider} kind="price" id={price.externalId} mode={mode} /> : null}
								</span>
							</td>
							<td className="text-end">
								<Switch
									className={tableSwitchClass}
									aria-label={`${price.active ? 'Retire' : 'Offer'} the ${INTERVAL_LABEL[price.interval].toLowerCase()} ${plan.displayName} price`}
									checked={price.active}
									disabled={!onTogglePrice}
									onCheckedChange={(active) => onTogglePrice?.(plan, price, active)}
								/>
							</td>
						</tr>
					))}
				</tbody>
			))}
		</TableSurface>
	);
}

/* ------------------------------------------------------------------ *
 * Meters
 * ------------------------------------------------------------------ */

type MeterCatalogTableProps = {
	meters: Meter[];
	onToggle?: (meter: Meter, active: boolean) => void;
	className?: string;
};

/** The meter catalog grouped by pool: unit, credit cost, reset, rollover cap, and aggregation. */
export function MeterCatalogTable({ meters, onToggle, className }: MeterCatalogTableProps) {
	const f = useBillingFormat();
	const pools = meters.filter((meter) => meter.meterType === 'usage_pool' && meter.slug !== 'universal');
	const groups = [
		...pools.map((pool) => ({ pool, rows: meters.filter((meter) => meter.categoryMeter === pool.slug && meter.meterType !== 'usage_pool') })),
		{ pool: undefined, rows: meters.filter((meter) => meter.meterType !== 'usage_pool' && (!meter.categoryMeter || meter.categoryMeter === 'universal')) },
	].filter((group) => group.rows.length > 0);
	return (
		<TableSurface className={className} minWidth="46rem">
			<thead className={tableHeadClass}>
				<tr>
					<th scope="col">Meter</th>
					<th scope="col">Unit</th>
					<th scope="col" className="text-end">
						Credit cost
					</th>
					<th scope="col">Resets</th>
					<th scope="col">Counts</th>
					<th scope="col" className="text-end">
						Active
					</th>
				</tr>
			</thead>
			{groups.map(({ pool, rows }) => (
				<tbody key={pool?.slug ?? 'loose'}>
					<tr className={tableGroupRowClass}>
						<th scope="rowgroup" colSpan={6}>
							{pool ? `${pool.displayName} pool` : 'Straight to universal'}
						</th>
					</tr>
					{rows.map((meter) => (
						<tr key={meter.slug} className={cn(tableRowClass, !meter.active && 'text-muted-foreground')}>
							<th scope="row" className="px-4 py-2 text-start font-normal">
								<span className="block text-foreground [overflow-wrap:anywhere]">{meter.displayName}</span>
								<span className="block font-mono text-[0.6875rem] text-subtle-foreground [overflow-wrap:anywhere]">{meter.slug}</span>
							</th>
							<td className="text-muted-foreground">{meter.unit}</td>
							<td className="text-end tabular-nums">
								{meter.creditCost === null ? <span className="text-subtle-foreground">No fallback</span> : meter.creditCost === 0 ? 'Free' : `${f.quantity(meter.creditCost)} cr`}
							</td>
							<td className="text-muted-foreground">
								{meter.periodInterval ? humanize(`${meter.periodInterval}ly`) : 'Never'}
								{meter.rolloverCap ? ` · rolls ${f.quantity(meter.rolloverCap, true)}` : ''}
							</td>
							<td className="text-muted-foreground">{meter.aggregation === 'peak' ? 'Peak' : 'Sum'}</td>
							<td className="text-end">
								<Switch
									className={tableSwitchClass}
									aria-label={`${meter.active ? 'Pause' : 'Resume'} ${meter.displayName}`}
									checked={meter.active}
									disabled={!onToggle}
									onCheckedChange={(active) => onToggle?.(meter, active)}
								/>
							</td>
						</tr>
					))}
				</tbody>
			))}
		</TableSurface>
	);
}

/* ------------------------------------------------------------------ *
 * Packs and codes
 * ------------------------------------------------------------------ */

type CreditPackTableProps = {
	packs: CreditPack[];
	creditsPerCent?: number;
	onToggle?: (pack: CreditPack, active: boolean) => void;
	onAdd?: () => void;
	className?: string;
};

/** Credit packs with the charge the credit rate produces, flagged when the advertised price is below it. */
export function CreditPackTable({ packs, creditsPerCent = 1, onToggle, className }: CreditPackTableProps) {
	const f = useBillingFormat();
	return (
		<TableSurface className={className} minWidth="40rem">
			<thead className={tableHeadClass}>
				<tr>
					<th scope="col">Pack</th>
					<th scope="col" className="text-end">
						Credits
					</th>
					<th scope="col" className="text-end">
						Advertised
					</th>
					<th scope="col" className="text-end">
						Charged
					</th>
					<th scope="col">Expiry</th>
					<th scope="col" className="text-end">
						Active
					</th>
				</tr>
			</thead>
			<tbody>
				{packs.map((pack) => {
					const charged = Math.ceil(pack.amount / creditsPerCent);
					const refused = pack.price.amountMinor < charged;
					return (
						<tr key={pack.id} className={cn(tableRowClass, !pack.active && 'text-muted-foreground')}>
							<th scope="row" className="px-4 py-2 text-start font-normal">
								<span className="block text-foreground [overflow-wrap:anywhere]">{pack.displayName}</span>
								<span className="block font-mono text-[0.6875rem] text-subtle-foreground [overflow-wrap:anywhere]">{pack.slug}</span>
							</th>
							<td className="text-end tabular-nums">{f.quantity(pack.amount)}</td>
							<td className="text-end tabular-nums">{f.money(pack.price, { precise: true })}</td>
							<td className="text-end tabular-nums">
								{refused ? (
									<Tooltip>
										<TooltipTrigger render={<span tabIndex={0} className="inline-flex" />}>
											<ToneBadge tone="danger">Below rate</ToneBadge>
										</TooltipTrigger>
										<TooltipContent>Checkout refuses this pack until its price is at least {f.money({ ...pack.price, amountMinor: charged }, { precise: true })}.</TooltipContent>
									</Tooltip>
								) : (
									<span className="text-foreground">{f.money({ ...pack.price, amountMinor: charged }, { precise: true })}</span>
								)}
							</td>
							<td className="text-muted-foreground">
								{pack.expiresAfterDays ? `${f.quantity(pack.expiresAfterDays)} ${plural(pack.expiresAfterDays, { one: 'day', other: 'days' })}` : 'Never'}
							</td>
							<td className="text-end">
								<Switch
									className={tableSwitchClass}
									aria-label={`${pack.active ? 'Stop selling' : 'Sell'} ${pack.displayName}`}
									checked={pack.active}
									disabled={!onToggle}
									onCheckedChange={(active) => onToggle?.(pack, active)}
								/>
							</td>
						</tr>
					);
				})}
			</tbody>
		</TableSurface>
	);
}

'use client';

import { Check, ChevronRight, Copy, Download, Plus, RefreshCw, Trash2 } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Dialog, DialogDescription, DialogFooter, DialogHeader, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Sheet, SheetContent, SheetDescription, SheetTitle } from '@/components/ui/sheet';
import { Switch } from '@/components/ui/switch';
import { focusRingClass, ToneBadge, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { CODE_PATTERN, CODE_STATUS, CodeGrantList, codeStatus, type DescribeTarget, generateCode, normalizeCode, RedemptionList } from '@/components/ui/billing-kit/codes';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { CREDIT_TYPE, dayKey } from '@/components/ui/billing-kit/format';
import { EmptyState, KeyValueList, nativeSelectClass, Panel, TableSurface, tableHeadClass, tableRowClass } from '@/components/ui/billing-kit/surface';
import type { CodeRedemption, CreditCode, CreditCodeDraft, CreditCodeItem, CreditTarget, CreditType } from '@/components/ui/billing-kit/types';

/** A credit target an operator can put in a code, with its display label. */
export type CodeTargetOption = { target: CreditTarget; label: string };

const LIMIT_CREDIT_TYPES: CreditType[] = ['permanent', 'period'];
const METER_CREDIT_TYPES: CreditType[] = ['permanent', 'period', 'rollover'];
const optionValue = (target: CreditTarget) => `${target.kind}:${target.key}`;

function parseTarget(value: string): CreditTarget {
	const [kind, ...rest] = value.split(':');
	return { kind: kind === 'limit' ? 'limit' : 'meter', key: rest.join(':') };
}

/** `YYYY-MM-DD` for a date input, read in UTC so the chosen day round-trips. */
const toDateInput = (iso?: string) => (iso ? dayKey(iso, 'UTC') : '');
/** Codes expire at the end of the chosen UTC day. */
const fromDateInput = (value: string) => (value ? `${value}T23:59:59.000Z` : undefined);

/* ------------------------------------------------------------------ *
 * Items editor
 * ------------------------------------------------------------------ */

type CodeItemsEditorProps = {
	items: CreditCodeItem[];
	onChange: (items: CreditCodeItem[]) => void;
	targets: CodeTargetOption[];
	error?: string;
};

/** Rows of target, amount, credit type, and lifetime. Limits only accept permanent or period credits. */
export function CodeItemsEditor({ items, onChange, targets, error }: CodeItemsEditorProps) {
	const id = React.useId();
	const used = new Set(items.map((item) => optionValue(item.target)));
	const meters = targets.filter((option) => option.target.kind === 'meter');
	const limits = targets.filter((option) => option.target.kind === 'limit');
	const update = (index: number, patch: Partial<CreditCodeItem>) => onChange(items.map((item, at) => (at === index ? { ...item, ...patch } : item)));
	const firstFree = targets.find((option) => !used.has(optionValue(option.target)));

	return (
		<fieldset className="flex flex-col gap-2" aria-describedby={error ? `${id}-error` : undefined}>
			<legend className="mb-1 text-xs text-muted-foreground">Grants</legend>
			{items.map((item, index) => {
				const types = item.target.kind === 'limit' ? LIMIT_CREDIT_TYPES : METER_CREDIT_TYPES;
				const renderOption = (option: CodeTargetOption) => {
					const value = optionValue(option.target);
					return (
						<option key={value} value={value} disabled={used.has(value) && value !== optionValue(item.target)}>
							{option.label}
						</option>
					);
				};
				return (
					<div key={index} className="grid grid-cols-[minmax(0,1fr)_6.5rem_auto] items-end gap-2 rounded-lg border border-border bg-muted/30 p-2.5 @lg/view:grid-cols-[minmax(0,1fr)_6.5rem_7.5rem_6rem_auto]">
						<label className="flex flex-col gap-1 text-[0.6875rem] text-muted-foreground">
							Credits for
							<select
								className={nativeSelectClass}
								value={optionValue(item.target)}
								onChange={(event) => {
									const target = parseTarget(event.target.value);
									update(index, { target, creditType: target.kind === 'limit' && item.creditType === 'rollover' ? 'permanent' : item.creditType });
								}}
							>
								{meters.length ? <optgroup label="Meters">{meters.map(renderOption)}</optgroup> : null}
								{limits.length ? <optgroup label="Limits">{limits.map(renderOption)}</optgroup> : null}
							</select>
						</label>
						<label className="flex flex-col gap-1 text-[0.6875rem] text-muted-foreground">
							Amount
							<input
								inputMode="numeric"
								value={item.amount ? String(item.amount) : ''}
								placeholder="36000"
								onChange={(event) => update(index, { amount: Number(event.target.value.replace(/\D/g, '')) || 0 })}
								className={cn(nativeSelectClass, 'tabular-nums')}
							/>
						</label>
						<TooltipIconButton label="Remove grant" size="sm" className="mb-1" disabled={items.length === 1} onClick={() => onChange(items.filter((_, at) => at !== index))}>
							<Trash2 aria-hidden="true" className="size-3.5" />
						</TooltipIconButton>
						<label className="col-span-1 flex flex-col gap-1 text-[0.6875rem] text-muted-foreground @lg/view:col-auto @lg/view:row-start-1 @lg/view:col-start-3">
							Type
							<select className={nativeSelectClass} value={item.creditType} onChange={(event) => update(index, { creditType: event.target.value as CreditType })}>
								{types.map((type) => (
									<option key={type} value={type}>
										{CREDIT_TYPE[type].label}
									</option>
								))}
							</select>
						</label>
						<label className="flex flex-col gap-1 text-[0.6875rem] text-muted-foreground @lg/view:row-start-1 @lg/view:col-start-4">
							Lasts (days)
							<input
								inputMode="numeric"
								value={item.expiresAfterDays ? String(item.expiresAfterDays) : ''}
								placeholder={item.target.kind === 'limit' ? 'n/a' : 'Forever'}
								disabled={item.creditType === 'period' || item.target.kind === 'limit'}
								onChange={(event) => update(index, { expiresAfterDays: Number(event.target.value.replace(/\D/g, '')) || undefined })}
								className={cn(nativeSelectClass, 'tabular-nums disabled:opacity-60')}
							/>
						</label>
					</div>
				);
			})}
			<div className="flex items-center justify-between gap-3">
				{error ? (
					<p id={`${id}-error`} className="text-xs text-destructive">
						{error}
					</p>
				) : (
					<span />
				)}
				<Button
					type="button"
					size="xs"
					variant="ghost"
					disabled={!firstFree}
					onClick={() => firstFree && onChange([...items, { target: firstFree.target, amount: 0, creditType: 'permanent' }])}
				>
					<Plus aria-hidden="true" />
					Add grant
				</Button>
			</div>
		</fieldset>
	);
}

function itemsError(items: CreditCodeItem[]) {
	if (items.length === 0) return 'Add at least one grant.';
	if (items.some((item) => !item.amount || item.amount <= 0)) return 'Every grant needs an amount above zero.';
	return undefined;
}

const emptyItem = (targets: CodeTargetOption[]): CreditCodeItem[] => (targets[0] ? [{ target: targets[0].target, amount: 0, creditType: 'permanent' }] : []);

/* ------------------------------------------------------------------ *
 * Create or edit one code
 * ------------------------------------------------------------------ */

type CreditCodeDialogProps = {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	/** The code being edited; absent to create one. */
	code?: CreditCode;
	targets: CodeTargetOption[];
	/** Codes already taken, to catch duplicates before the host is called. */
	existingCodes: string[];
	/** Saves the draft; reject with an Error to keep the dialog open with its message. */
	onSave: (draft: CreditCodeDraft) => Promise<void> | void;
};

type CodeForm = { code: string; note: string; items: CreditCodeItem[]; unlimited: boolean; maxRedemptions: string; expires: string; active: boolean };

const formFor = (code: CreditCode | undefined, targets: CodeTargetOption[]): CodeForm => ({
	code: code?.code ?? '',
	note: code?.note ?? '',
	items: code?.items ?? emptyItem(targets),
	unlimited: code ? code.maxRedemptions === null : false,
	maxRedemptions: code?.maxRedemptions ? String(code.maxRedemptions) : '100',
	expires: toDateInput(code?.expiresAt),
	active: code?.active ?? true,
});

/**
 * One code: the string (typed or generated), what it grants, how many
 * accounts can redeem it, when it expires, and whether it is live. A code
 * that has been redeemed keeps its string, so shared links keep working.
 */
export function CreditCodeDialog({ open, onOpenChange, code, targets, existingCodes, onSave }: CreditCodeDialogProps) {
	const [form, setForm] = React.useState<CodeForm>(() => formFor(code, targets));
	const [errors, setErrors] = React.useState<Partial<Record<'code' | 'items' | 'max' | 'save', string>>>({});
	const [busy, setBusy] = React.useState(false);
	const id = React.useId();

	// Each opening starts from the code being edited (or a blank form), during render so stale input never shows.
	const session = open ? (code?.id ?? 'new') : null;
	const [lastSession, setLastSession] = React.useState(session);
	if (session !== lastSession) {
		setLastSession(session);
		if (session !== null) {
			setForm(formFor(code, targets));
			setErrors({});
			setBusy(false);
		}
	}

	const locked = Boolean(code && code.redemptions > 0);
	const taken = new Set(existingCodes.map(normalizeCode));
	if (code) taken.delete(normalizeCode(code.code));
	const set = (patch: Partial<CodeForm>) => setForm((current) => ({ ...current, ...patch }));

	const submit = async (event: React.FormEvent) => {
		event.preventDefault();
		const normalized = normalizeCode(form.code);
		const max = Number(form.maxRedemptions);
		const next = {
			code: !CODE_PATTERN.test(normalized) ? 'Use 3–32 letters, digits, or dashes.' : taken.has(normalized) ? 'That code already exists.' : undefined,
			items: itemsError(form.items),
			max: !form.unlimited && !(Number.isInteger(max) && max > 0) ? 'Enter a whole number above zero, or allow unlimited.' : undefined,
		};
		setErrors(next);
		if (next.code || next.items || next.max) return;
		setBusy(true);
		try {
			await onSave({
				code: normalized,
				items: form.items,
				maxRedemptions: form.unlimited ? null : max,
				expiresAt: fromDateInput(form.expires),
				active: form.active,
				note: form.note.trim() || undefined,
				batch: code?.batch,
			});
			onOpenChange(false);
		} catch (reason) {
			setErrors({ save: reason instanceof Error ? reason.message : 'The code could not be saved.' });
		} finally {
			setBusy(false);
		}
	};

	return (
		<Dialog open={open} onOpenChange={(next) => (busy ? undefined : onOpenChange(next))}>
			<DialogPopup className="max-w-2xl">
				<form onSubmit={submit} noValidate className="@container/view flex min-h-0 flex-col">
					<DialogHeader className="gap-1.5 pb-3">
						<DialogTitle className="text-base font-medium">{code ? `Edit ${code.code}` : 'New code'}</DialogTitle>
						<DialogDescription className="text-[0.8125rem]">
							Each billing account can redeem a code once. Changes apply to future redemptions only.
						</DialogDescription>
					</DialogHeader>
					<div className="flex min-h-0 flex-col gap-4 overflow-y-auto px-6 pb-5">
						<div className="grid grid-cols-1 gap-3 @lg/view:grid-cols-2">
							<div className="flex flex-col gap-1">
								<label htmlFor={`${id}-code`} className="text-xs text-muted-foreground">
									Code
								</label>
								<div className="flex gap-2">
									<Input
										id={`${id}-code`}
										size="sm"
										value={form.code}
										disabled={locked}
										onChange={(event) => set({ code: event.target.value.toUpperCase() })}
										placeholder="LAUNCH-2026"
										autoComplete="off"
										spellCheck={false}
										aria-invalid={errors.code ? true : undefined}
										aria-describedby={`${id}-code-help`}
										className="font-mono"
									/>
									<TooltipIconButton label="Generate a code" size="sm" disabled={locked} onClick={() => set({ code: generateCode() })}>
										<RefreshCw aria-hidden="true" className="size-3.5" />
									</TooltipIconButton>
								</div>
								<p id={`${id}-code-help`} className={cn('text-xs', errors.code ? 'text-destructive' : 'text-muted-foreground')}>
									{errors.code ?? (locked ? 'Already redeemed, so the code itself can’t change.' : 'Case and spaces are ignored when people redeem it.')}
								</p>
							</div>
							<label htmlFor={`${id}-note`} className="flex flex-col gap-1 text-xs text-muted-foreground">
								Note (internal)
								<Input id={`${id}-note`} size="sm" value={form.note} onChange={(event) => set({ note: event.target.value })} placeholder="Hackathon, Sep 2026" />
							</label>
						</div>
						<CodeItemsEditor items={form.items} onChange={(items) => set({ items })} targets={targets} error={errors.items} />
						<div className="grid grid-cols-1 gap-3 @lg/view:grid-cols-3">
							<div className="flex flex-col gap-1">
								<label htmlFor={`${id}-max`} className="text-xs text-muted-foreground">
									Redemptions allowed
								</label>
								<input
									id={`${id}-max`}
									inputMode="numeric"
									value={form.unlimited ? '' : form.maxRedemptions}
									placeholder={form.unlimited ? 'Unlimited' : '100'}
									disabled={form.unlimited}
									onChange={(event) => set({ maxRedemptions: event.target.value.replace(/\D/g, '') })}
									aria-invalid={errors.max ? true : undefined}
									className={cn(nativeSelectClass, 'tabular-nums disabled:opacity-60')}
								/>
								<label className="flex items-center gap-2 text-xs text-muted-foreground">
									<input type="checkbox" className="accent-primary" checked={form.unlimited} onChange={(event) => set({ unlimited: event.target.checked })} />
									Unlimited
								</label>
								{errors.max ? <p className="text-xs text-destructive">{errors.max}</p> : null}
							</div>
							<label htmlFor={`${id}-expires`} className="flex flex-col gap-1 text-xs text-muted-foreground">
								Code expires (UTC)
								<input id={`${id}-expires`} type="date" value={form.expires} onChange={(event) => set({ expires: event.target.value })} className={nativeSelectClass} />
								<span>{form.expires ? 'Redemptions stop at the end of that day.' : 'Leave empty to keep it open.'}</span>
							</label>
							<div className="flex flex-col gap-1 text-xs text-muted-foreground">
								<span id={`${id}-active`}>Live</span>
								<span className="flex items-center gap-2">
									<Switch aria-labelledby={`${id}-active`} checked={form.active} onCheckedChange={(active) => set({ active })} />
									<span>{form.active ? 'Accepting redemptions' : 'Paused'}</span>
								</span>
							</div>
						</div>
						{errors.save ? (
							<p role="alert" className="text-[0.8125rem] text-destructive">
								{errors.save}
							</p>
						) : null}
					</div>
					<DialogFooter>
						<Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => onOpenChange(false)}>
							Cancel
						</Button>
						<Button type="submit" size="sm" disabled={busy} aria-busy={busy || undefined}>
							{busy ? 'Saving…' : code ? 'Save code' : 'Create code'}
						</Button>
					</DialogFooter>
				</form>
			</DialogPopup>
		</Dialog>
	);
}

/* ------------------------------------------------------------------ *
 * Bulk codes
 * ------------------------------------------------------------------ */

type BulkCodeDialogProps = {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	targets: CodeTargetOption[];
	existingCodes: string[];
	/** Creates every draft; reject with an Error to stay on the form. */
	onCreate: (drafts: CreditCodeDraft[]) => Promise<void> | void;
};

const MAX_BATCH = 500;

/** Draws `count` unique single-use codes that collide with nothing already taken. */
function drawCodes(prefix: string, count: number, taken: ReadonlySet<string>) {
	const codes = new Set<string>();
	while (codes.size < count) {
		const code = generateCode(prefix);
		if (!taken.has(code)) codes.add(code);
	}
	return [...codes];
}

/**
 * Many single-use codes in one go, e.g. for an event: a prefix, a count,
 * what each grants, and an expiry. After creation the codes can be copied
 * or downloaded as CSV.
 */
export function BulkCodeDialog({ open, onOpenChange, targets, existingCodes, onCreate }: BulkCodeDialogProps) {
	const f = useBillingFormat();
	const [prefix, setPrefix] = React.useState('');
	const [count, setCount] = React.useState('50');
	const [items, setItems] = React.useState<CreditCodeItem[]>(() => emptyItem(targets));
	const [expires, setExpires] = React.useState('');
	const [note, setNote] = React.useState('');
	const [errors, setErrors] = React.useState<Partial<Record<'prefix' | 'count' | 'items' | 'save', string>>>({});
	const [busy, setBusy] = React.useState(false);
	const [created, setCreated] = React.useState<string[] | null>(null);
	const [copied, setCopied] = React.useState(false);
	const id = React.useId();

	const [wasOpen, setWasOpen] = React.useState(open);
	if (open !== wasOpen) {
		setWasOpen(open);
		if (open) {
			setPrefix('');
			setCount('50');
			setItems(emptyItem(targets));
			setExpires('');
			setNote('');
			setErrors({});
			setCreated(null);
			setCopied(false);
		}
	}

	const submit = async (event: React.FormEvent) => {
		event.preventDefault();
		const head = normalizeCode(prefix);
		const total = Number(count);
		const next = {
			prefix: head && !/^[A-Z0-9-]{1,12}$/.test(head) ? 'Use up to 12 letters, digits, or dashes.' : undefined,
			count: !(Number.isInteger(total) && total >= 1 && total <= MAX_BATCH) ? `Between 1 and ${MAX_BATCH}.` : undefined,
			items: itemsError(items),
		};
		setErrors(next);
		if (next.prefix || next.count || next.items) return;
		const batch = `${head || 'BATCH'}-${generateCode('', 4)}`;
		const codes = drawCodes(head, total, new Set(existingCodes.map(normalizeCode)));
		setBusy(true);
		try {
			await onCreate(codes.map((code) => ({ code, items, maxRedemptions: 1, expiresAt: fromDateInput(expires), active: true, note: note.trim() || undefined, batch })));
			setCreated(codes);
		} catch (reason) {
			setErrors({ save: reason instanceof Error ? reason.message : 'The codes could not be created.' });
		} finally {
			setBusy(false);
		}
	};

	const download = () => {
		if (!created) return;
		const url = URL.createObjectURL(new Blob([`code\n${created.join('\n')}\n`], { type: 'text/csv' }));
		const link = document.createElement('a');
		link.href = url;
		link.download = `${normalizeCode(prefix) || 'codes'}-${created.length}.csv`;
		link.click();
		URL.revokeObjectURL(url);
	};

	return (
		<Dialog open={open} onOpenChange={(next) => (busy ? undefined : onOpenChange(next))}>
			<DialogPopup className="max-w-2xl">
				{created ? (
					<>
						<DialogHeader className="gap-1.5 pb-3">
							<DialogTitle className="text-base font-medium">{f.quantity(created.length)} codes created</DialogTitle>
							<DialogDescription className="text-[0.8125rem]">Each works once. Copy or download them now; they are also listed in the catalog.</DialogDescription>
						</DialogHeader>
						<div className="px-6 pb-5">
							<pre className="max-h-64 overflow-y-auto rounded-lg border border-border bg-muted/40 px-3 py-2 font-mono text-[0.8125rem] leading-6 text-foreground">{created.join('\n')}</pre>
						</div>
						<DialogFooter>
							<Button size="sm" variant="ghost" onClick={download}>
								<Download aria-hidden="true" />
								Download CSV
							</Button>
							<Button
								size="sm"
								variant="outline"
								onClick={() => {
									navigator.clipboard?.writeText(created.join('\n')).then(
										() => setCopied(true),
										() => {},
									);
								}}
							>
								{copied ? <Check aria-hidden="true" /> : <Copy aria-hidden="true" />}
								{copied ? 'Copied' : 'Copy all'}
							</Button>
							<Button size="sm" onClick={() => onOpenChange(false)}>
								Done
							</Button>
						</DialogFooter>
					</>
				) : (
					<form onSubmit={submit} noValidate className="@container/view flex min-h-0 flex-col">
						<DialogHeader className="gap-1.5 pb-3">
							<DialogTitle className="text-base font-medium">Bulk create codes</DialogTitle>
							<DialogDescription className="text-[0.8125rem]">Single-use codes that share what they grant, e.g. one per attendee.</DialogDescription>
						</DialogHeader>
						<div className="flex min-h-0 flex-col gap-4 overflow-y-auto px-6 pb-5">
							<div className="grid grid-cols-1 gap-3 @lg/view:grid-cols-3">
								<label htmlFor={`${id}-prefix`} className="flex flex-col gap-1 text-xs text-muted-foreground">
									Prefix
									<Input
										id={`${id}-prefix`}
										size="sm"
										value={prefix}
										onChange={(event) => setPrefix(event.target.value.toUpperCase())}
										placeholder="HACK"
										aria-invalid={errors.prefix ? true : undefined}
										className="font-mono"
									/>
									<span className={errors.prefix ? 'text-destructive' : undefined}>{errors.prefix ?? `e.g. ${normalizeCode(prefix) || 'HACK'}-7KQM-X3TP`}</span>
								</label>
								<label htmlFor={`${id}-count`} className="flex flex-col gap-1 text-xs text-muted-foreground">
									How many
									<input
										id={`${id}-count`}
										inputMode="numeric"
										value={count}
										onChange={(event) => setCount(event.target.value.replace(/\D/g, ''))}
										aria-invalid={errors.count ? true : undefined}
										className={cn(nativeSelectClass, 'tabular-nums')}
									/>
									<span className={errors.count ? 'text-destructive' : undefined}>{errors.count ?? `Up to ${MAX_BATCH} at a time.`}</span>
								</label>
								<label htmlFor={`${id}-expires`} className="flex flex-col gap-1 text-xs text-muted-foreground">
									Codes expire (UTC)
									<input id={`${id}-expires`} type="date" value={expires} onChange={(event) => setExpires(event.target.value)} className={nativeSelectClass} />
								</label>
							</div>
							<CodeItemsEditor items={items} onChange={setItems} targets={targets} error={errors.items} />
							<label htmlFor={`${id}-note`} className="flex flex-col gap-1 text-xs text-muted-foreground">
								Note (internal)
								<Input id={`${id}-note`} size="sm" value={note} onChange={(event) => setNote(event.target.value)} placeholder="Campus tour, Oct 2026" />
							</label>
							{errors.save ? (
								<p role="alert" className="text-[0.8125rem] text-destructive">
									{errors.save}
								</p>
							) : null}
						</div>
						<DialogFooter>
							<Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => onOpenChange(false)}>
								Cancel
							</Button>
							<Button type="submit" size="sm" disabled={busy} aria-busy={busy || undefined}>
								{busy ? 'Creating…' : `Create ${Number(count) > 0 ? f.quantity(Number(count)) : ''} codes`}
							</Button>
						</DialogFooter>
					</form>
				)}
			</DialogPopup>
		</Dialog>
	);
}

