export type GrantCreditsRequest = {
	customerId: string;
	meterSlug: string;
	amount: number;
	creditType: CreditType;
	expiresInDays?: number;
	reason: string;
};

type GrantCreditsFormProps = {
	customerId: string;
	meters: Meter[];
	onGrant: (request: GrantCreditsRequest) => Promise<void> | void;
	onCancel?: () => void;
};

/** Grants credits to one customer: meter, amount, type, optional expiry, and a reason for the ledger. */
export function GrantCreditsForm({ customerId, meters, onGrant, onCancel }: GrantCreditsFormProps) {
	const grantable = meters.filter((meter) => meter.active && meter.meterType !== 'boolean');
	const [meterSlug, setMeterSlug] = React.useState(grantable.find((meter) => meter.slug === 'universal')?.slug ?? grantable[0]?.slug ?? '');
	const [amount, setAmount] = React.useState('');
	const [creditType, setCreditType] = React.useState<CreditType>('permanent');
	const [expires, setExpires] = React.useState('');
	const [reason, setReason] = React.useState('');
	const [busy, setBusy] = React.useState(false);
	const [error, setError] = React.useState<string | null>(null);
	const id = React.useId();
	const value = Number(amount.replace(/[, _]/g, ''));
	const valid = Number.isFinite(value) && value > 0 && reason.trim().length > 0;

	return (
		<form
			className="flex flex-col gap-3"
			onSubmit={async (event) => {
				event.preventDefault();
				if (!valid) return;
				setBusy(true);
				setError(null);
				try {
					await onGrant({ customerId, meterSlug, amount: Math.round(value), creditType, expiresInDays: expires ? Number(expires) : undefined, reason: reason.trim() });
				} catch (reason_) {
					setError(reason_ instanceof Error ? reason_.message : 'The grant failed.');
				} finally {
					setBusy(false);
				}
			}}
		>
			<div className="grid grid-cols-1 gap-3 @md/view:grid-cols-2">
				<label htmlFor={`${id}-meter`} className="flex flex-col gap-1 text-xs text-muted-foreground">
					Meter
					<select
						id={`${id}-meter`}
						value={meterSlug}
						onChange={(event) => setMeterSlug(event.target.value)}
						className={nativeSelectClass}
					>
						{grantable.map((meter) => (
							<option key={meter.slug} value={meter.slug}>
								{meter.displayName}
							</option>
						))}
					</select>
				</label>
				<label htmlFor={`${id}-amount`} className="flex flex-col gap-1 text-xs text-muted-foreground">
					Amount
					<Input id={`${id}-amount`} size="sm" inputMode="numeric" value={amount} placeholder="5,000" onChange={(event) => setAmount(event.target.value)} className="tabular-nums" />
				</label>
			</div>
			<div className="flex flex-col gap-1 text-xs text-muted-foreground">
				<span id={`${id}-type`}>Type</span>
				<Segmented
					label="Credit type"
					value={creditType}
					onChange={setCreditType}
					options={(['permanent', 'period', 'rollover'] as const).map((type) => ({ value: type, label: CREDIT_TYPE[type].label }))}
				/>
				<span>{CREDIT_TYPE[creditType].description}</span>
			</div>
			<div className="grid grid-cols-1 gap-3 @md/view:grid-cols-[8rem_minmax(0,1fr)]">
				<label htmlFor={`${id}-expires`} className="flex flex-col gap-1 text-xs text-muted-foreground">
					Expires after
					<span className="flex h-8 items-center rounded-md border border-border bg-card pe-2 shadow-2xs focus-within:ring-[3px] focus-within:ring-ring/50">
						<input
							id={`${id}-expires`}
							inputMode="numeric"
							value={expires}
							placeholder="Never"
							onChange={(event) => setExpires(event.target.value.replace(/\D/g, ''))}
							className="h-full w-full min-w-0 bg-transparent px-2 text-[0.8125rem] text-foreground tabular-nums outline-none placeholder:text-subtle-foreground"
						/>
						<span className="text-xs text-muted-foreground">days</span>
					</span>
				</label>
				<label htmlFor={`${id}-reason`} className="flex flex-col gap-1 text-xs text-muted-foreground">
					Reason (shown in the ledger)
					<Input id={`${id}-reason`} size="sm" value={reason} placeholder="Goodwill after the Sep 12 incident" onChange={(event) => setReason(event.target.value)} />
				</label>
			</div>
			{error ? (
				<p role="alert" className="text-xs text-destructive">
					{error}
				</p>
			) : null}
			<div className="flex justify-end gap-2">
				{onCancel ? (
					<Button type="button" size="xs" variant="ghost" onClick={onCancel}>
						Cancel
					</Button>
				) : null}
				<Button type="submit" size="xs" disabled={!valid || busy} aria-busy={busy || undefined}>
					{busy ? 'Granting…' : 'Grant credits'}
				</Button>
			</div>
		</form>
	);
}

type CustomerDetailSheetProps = {
	customer?: CustomerSummary;
	plans: Plan[];
	meters: Meter[];
	provider?: BillingProviderDescriptor;
	mode?: ProviderMode;
	open: boolean;
	onOpenChange: (open: boolean) => void;
	onGrantCredits?: (request: GrantCreditsRequest) => Promise<void> | void;
	onRemoveOverride?: (customer: CustomerSummary, override: PlanOverride) => void;
	onCancelScheduledChange?: (customer: CustomerSummary) => void;
	/** What to show while `customer.detail` is absent: still loading (the default), or known to be unavailable. */
	detailStatus?: 'loading' | 'unavailable';
};

/**
 * One customer in depth, for an operator: plan and standing, balances,
 * credits (with a grant form), per-customer overrides and request windows,
 * the provider operations log, and invoices.
 */
export function CustomerDetailSheet({
	customer,
	plans,
	meters,
	provider,
	mode = 'live',
	open,
	onOpenChange,
	onGrantCredits,
	onRemoveOverride,
	onCancelScheduledChange,
	detailStatus = 'loading',
}: CustomerDetailSheetProps) {
	const f = useBillingFormat();
	const [granting, setGranting] = React.useState(false);
	// Close the grant form when another customer opens, during render rather than in an effect.
	const [forId, setForId] = React.useState(customer?.id);
	if (forId !== customer?.id) {
		setForId(customer?.id);
		setGranting(false);
	}
	if (!customer) return null;
	const plan = plans.find((candidate) => candidate.id === customer.planId);
	const meterBySlug = new Map(meters.map((meter) => [meter.slug, meter]));
	const detail = customer.detail;
	const balances = [...(detail?.balances ?? [])]
		.filter((balance) => meterBySlug.get(balance.meterSlug)?.meterType !== 'usage_pool' || balance.meterSlug === 'universal')
		.sort((a, b) => (isUnlimited(b.effectiveLimit) ? -1 : b.currentUsage / Math.max(1, b.effectiveLimit)) - (isUnlimited(a.effectiveLimit) ? -1 : a.currentUsage / Math.max(1, a.effectiveLimit)))
		.slice(0, 6);

	return (
		<Sheet open={open} onOpenChange={onOpenChange}>
			<SheetContent side="right" className="w-[34rem] max-w-[94vw] gap-0 p-0 sm:max-w-[34rem]">
				<div className="flex flex-col gap-3 border-b border-border px-5 pt-5 pb-4">
					<div className="flex flex-wrap items-center gap-2 pe-8">
						<SheetTitle className="min-w-0 text-base font-medium [overflow-wrap:anywhere]">{customer.name}</SheetTitle>
						<LifecycleBadge lifecycle={customer.lifecycle} />
					</div>
					<SheetDescription className="text-[0.8125rem]">
						{plan?.displayName ?? customer.planId} · {f.money(customer.mrr)}/mo · customer since {f.date(customer.since)}
					</SheetDescription>
					{customer.externalId ? <ExternalRef provider={provider} kind="customer" id={customer.externalId} mode={mode} className="self-start" /> : null}
				</div>
				<div className="@container/view flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto bg-background px-5 py-5 [&>*]:shrink-0">
					{customer.scheduledChange ? (
						<div className="flex flex-wrap items-center gap-3 rounded-lg border border-info/25 bg-info/[0.06] px-3 py-2.5 text-[0.8125rem]">
							<CalendarClock aria-hidden="true" className="size-3.5 text-info" />
							<span className="min-w-0 flex-1 text-foreground">
								Moves to {plans.find((candidate) => candidate.id === customer.scheduledChange!.planId)?.displayName} on {f.date(customer.scheduledChange.effectiveAt)}
							</span>
							{onCancelScheduledChange ? (
								<Button size="xs" variant="outline" onClick={() => onCancelScheduledChange(customer)}>
									Cancel change
								</Button>
							) : null}
						</div>
					) : null}

					{!detail ? (
						<p role="status" className="text-[0.8125rem] text-muted-foreground">
							{detailStatus === 'unavailable' ? 'Details are not available for this customer.' : 'Loading details…'}
						</p>
					) : (
						<>
							<Panel title="Balances" description="Busiest meters this period.">
								<ul className="flex flex-col">
									{balances.map((balance, index) => {
										const meter = meterBySlug.get(balance.meterSlug);
										return (
											<li key={balance.meterSlug} className={cn('flex flex-col gap-1.5 py-2', index > 0 && cn('border-t', dashedRule))}>
												<span className="flex items-center justify-between gap-3">
													<span title={meter?.displayName ?? balance.meterSlug} className="line-clamp-2 min-w-0 text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">
														<bdi>{meter?.displayName ?? balance.meterSlug}</bdi>
													</span>
													<UsageFigure used={balance.currentUsage} limit={balance.effectiveLimit} unit={meter?.unit ?? ''} className="text-xs" />
												</span>
												<AllowanceBar used={balance.currentUsage} limit={balance.effectiveLimit} label={meter?.displayName ?? balance.meterSlug} size="sm" planMarker={balance.planLimit} />
											</li>
										);
									})}
								</ul>
							</Panel>

							<Panel
								title="Credits"
								actions={
									onGrantCredits && !granting ? (
										<Button size="xs" variant="outline" onClick={() => setGranting(true)}>
											<Gift aria-hidden="true" />
											Grant
										</Button>
									) : null
								}
							>
								{granting && onGrantCredits ? (
									<div className={cn('mb-3 rounded-lg border border-border bg-muted/30 p-3')}>
										<GrantCreditsForm
											customerId={customer.id}
											meters={meters}
											onCancel={() => setGranting(false)}
											onGrant={async (request) => {
												await onGrantCredits(request);
												setGranting(false);
											}}
										/>
									</div>
								) : null}
								<CreditGrantList grants={detail.grants} meterName={(slug) => meterBySlug.get(slug)?.displayName ?? slug} />
							</Panel>

							<Panel title="Overrides" description="Per-customer limits that beat the plan until they expire.">
								{detail.overrides.length === 0 ? (
									<p className="text-[0.8125rem] text-muted-foreground">None. This customer gets exactly what the plan says.</p>
								) : (
									<ul className="flex flex-col">
										{detail.overrides.map((override, index) => (
											<li key={override.id} className={cn('flex items-center gap-3 py-2', index > 0 && cn('border-t', dashedRule))}>
												<SlidersHorizontal aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
												<span className="min-w-0 flex-1">
													<span className="block text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">
														{override.limitName} <span className="inline-block rtl:-scale-x-100">→</span> {isUnlimited(override.maxValue) ? 'unlimited' : f.quantity(override.maxValue)}
													</span>
													<span className="block text-xs text-muted-foreground [overflow-wrap:anywhere]">
														{override.reason ?? 'No reason given'}
														{override.expiresAt ? ` · until ${f.date(override.expiresAt)}` : ''}
													</span>
												</span>
												{onRemoveOverride ? (
													<Button size="xs" variant="ghost" onClick={() => onRemoveOverride(customer, override)}>
														Remove
													</Button>
												) : null}
											</li>
										))}
									</ul>
								)}
							</Panel>

							{detail.rateWindows.length > 0 ? (
								<Panel title="Request windows" bodyClassName="p-0">
									<table className="w-full border-collapse text-[0.8125rem]">
										<thead className={tableHeadClass}>
											<tr>
												<th scope="col">Meter</th>
												<th scope="col">Window</th>
												<th scope="col" className="text-end">
													Max
												</th>
											</tr>
										</thead>
										<tbody>
											{detail.rateWindows.map((window) => (
												<tr key={window.id} className={tableRowClass}>
													<td className="text-foreground">
														{meterBySlug.get(window.meterSlug)?.displayName ?? window.meterSlug}
														<span className="block text-xs text-muted-foreground">{window.scope === 'entity' ? 'Whole account' : 'Per member'}</span>
													</td>
													<td className="text-muted-foreground">
														{window.window} · lock {window.lockout}
													</td>
													<td className="text-end tabular-nums">
														<span className="inline-flex items-center gap-2">
															{window.override ? <ToneBadge tone="primary">Override</ToneBadge> : null}
															{isUnlimited(window.maxRequests) ? 'None' : f.quantity(window.maxRequests)}
														</span>
													</td>
												</tr>
											))}
										</tbody>
									</table>
								</Panel>
							) : null}

							<Panel title="Provider operations" description="Idempotent calls to the provider, newest first.">
								<ol className="flex flex-col">
									{detail.operations.map((operation, index) => (
										<li key={operation.id} className={cn('flex flex-wrap items-center gap-x-3 gap-y-1 py-2', index > 0 && cn('border-t', dashedRule))}>
											<code className="font-mono text-xs [overflow-wrap:anywhere] text-foreground">{operation.action}</code>
											<StatusBadge presentation={OPERATION_STATE[operation.state]} />
											<span className="ms-auto text-xs text-muted-foreground tabular-nums">{f.date(operation.createdAt, 'short', true)}</span>
											{operation.errorCode ? <span className="w-full text-xs text-destructive [overflow-wrap:anywhere]">{operation.errorCode}</span> : null}
										</li>
									))}
								</ol>
							</Panel>

							{detail.invoices.length > 0 ? <InvoiceTable invoices={detail.invoices.slice(0, 4)} /> : null}
						</>
					)}
				</div>
			</SheetContent>
		</Sheet>
	);
}

'use client';

import { BellRing, Check, Lock, Plus, Trash2 } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { ToneBadge, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { AllowanceBar } from '@/components/ui/billing-kit/allowance';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { isUnlimited, unitFor, usageLevel } from '@/components/ui/billing-kit/format';
import { dashedRule, EmptyState, nativeSelectClass } from '@/components/ui/billing-kit/surface';
import type { FeatureCap, LimitCounter, UsageAlert } from '@/components/ui/billing-kit/types';

type LimitListProps = {
	limits: LimitCounter[];
	className?: string;
};

/** Counted limits such as databases and seats: used of allowed, with the soft limit as a warning. */
export function LimitList({ limits, className }: LimitListProps) {
	const f = useBillingFormat();
	return (
		<ul className={cn('flex flex-col', className)}>
			{limits.map((limit, index) => {
				const level = usageLevel(limit.used, limit.max, limit.softMax && limit.max > 0 ? limit.softMax / limit.max : 0.8);
				return (
					<li key={limit.name} className={cn('flex flex-col gap-2 py-3', index > 0 && cn('border-t', dashedRule))}>
						<div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
							<span className="min-w-0 text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">
								{limit.label}
								{limit.window ? <span className="text-muted-foreground"> · {limit.window}</span> : null}
							</span>
							<span className="text-[0.8125rem] tabular-nums [overflow-wrap:anywhere]">
								<span className="whitespace-nowrap">
									<span className={cn('font-medium', level === 'exhausted' || level === 'over' ? 'text-destructive' : 'text-foreground')}>{f.quantity(limit.used)}</span>
									<span className="text-muted-foreground">
										{' of '}
										{isUnlimited(limit.max) ? 'unlimited' : f.quantity(limit.max)}
									</span>
								</span>
								<span className="text-muted-foreground"> {unitFor(limit.max, limit.unit, limit.unitSingular)}</span>
							</span>
						</div>
						<AllowanceBar used={limit.used} limit={limit.max} label={limit.label} size="sm" soft={limit.softMax && limit.max > 0 ? limit.softMax / limit.max : undefined} />
						{level === 'exhausted' || level === 'over' ? (
							<p className="text-xs text-destructive">At the limit. New {limit.unit} are refused until you upgrade or free one up.</p>
						) : null}
					</li>
				);
			})}
		</ul>
	);
}

type FeatureCapListProps = {
	caps: FeatureCap[];
	/** Asks the host to show the plans that include a cap. */
	onUnlock?: (cap: FeatureCap) => void;
	className?: string;
};

/** Plan features: on, off with a way to unlock, or a numeric setting. */
export function FeatureCapList({ caps, onUnlock, className }: FeatureCapListProps) {
	const f = useBillingFormat();
	return (
		<ul className={cn('grid grid-cols-1 gap-2 @xl/view:grid-cols-2', className)}>
			{caps.map((cap) => {
				const on = cap.value > 0;
				return (
					<li key={cap.name} className={cn('flex items-start gap-3 rounded-lg border px-3 py-2.5', on ? 'border-border bg-card' : 'border-dashed border-foreground/15')}>
						<span
							aria-hidden="true"
							className={cn('mt-0.5 grid size-5 shrink-0 place-items-center rounded-md', on ? 'bg-success/15 text-success' : 'bg-muted text-muted-foreground')}
						>
							{on ? <Check className="size-3" /> : <Lock className="size-3" />}
						</span>
						<span className="min-w-0 flex-1">
							<span className="flex items-center gap-2 text-[0.8125rem] font-medium text-foreground [overflow-wrap:anywhere]">
								{cap.label}
								<span className="sr-only">{on ? ', included' : ', not included'}</span>
							</span>
							{cap.description ? (
								<span title={cap.description} className="mt-0.5 line-clamp-3 block text-pretty text-xs text-muted-foreground [overflow-wrap:anywhere]">
									{cap.description}
								</span>
							) : null}
						</span>
						{cap.kind === 'number' && on ? (
							<span className="max-w-[50%] min-w-0 text-end text-[0.8125rem] text-foreground tabular-nums [overflow-wrap:anywhere]">
								{f.quantity(cap.value)}
								{cap.unit ? <span className="text-muted-foreground"> {unitFor(cap.value, cap.unit, cap.unitSingular)}</span> : null}
							</span>
						) : !on && onUnlock ? (
							<Button size="xs" variant="ghost" onClick={() => onUnlock(cap)}>
								Unlock
							</Button>
						) : null}
					</li>
				);
			})}
		</ul>
	);
}

type AlertTarget = { value: string; label: string };

type UsageAlertListProps = {
	alerts: UsageAlert[];
	targets: AlertTarget[];
	onChange: (alerts: UsageAlert[]) => void;
	readOnly?: boolean;
	className?: string;
};

/**
 * Usage alerts: notify when a meter or limit crosses a share of its allowance.
 * Each row toggles; new alerts pick a target and a percentage.
 */
export function UsageAlertList({ alerts, targets, onChange, readOnly, className }: UsageAlertListProps) {
	const f = useBillingFormat();
	const [chosenTarget, setTarget] = React.useState(targets[0]?.value ?? '');
	// Fall back to the first target when the chosen one is no longer offered.
	const target = targets.some((candidate) => candidate.value === chosenTarget) ? chosenTarget : (targets[0]?.value ?? '');
	const [threshold, setThreshold] = React.useState(80);
	const targetId = React.useId();
	const thresholdId = React.useId();
	const labels = new Map(targets.map((candidate) => [candidate.value, candidate.label]));
	const label = (value: string) => labels.get(value) ?? value;

	return (
		<div className={cn('flex flex-col gap-3', className)}>
			{alerts.length === 0 ? (
				<EmptyState icon={BellRing} title="No alerts" description="Get told before a meter runs out, not after." className="py-6" />
			) : (
				<ul className="flex flex-col">
					{alerts.map((alert, index) => (
						<li key={alert.id} className={cn('flex items-center gap-3 py-2.5', index > 0 && cn('border-t', dashedRule))}>
							<Switch
								aria-label={`${alert.enabled ? 'Turn off' : 'Turn on'} the ${label(alert.target)} alert`}
								checked={alert.enabled}
								disabled={readOnly}
								onCheckedChange={(enabled) => onChange(alerts.map((candidate) => (candidate.id === alert.id ? { ...candidate, enabled } : candidate)))}
							/>
							<span title={label(alert.target)} className={cn('line-clamp-2 min-w-0 flex-1 text-[0.8125rem] [overflow-wrap:anywhere]', alert.enabled ? 'text-foreground' : 'text-muted-foreground')}>
								<bdi>{label(alert.target)}</bdi>
							</span>
							<ToneBadge tone={alert.enabled ? 'warning' : 'neutral'}>
								at {f.quantity(alert.threshold)}
								{alert.kind === 'percent' ? '%' : ''}
							</ToneBadge>
							{readOnly ? null : (
								<TooltipIconButton label={`Remove the ${label(alert.target)} alert`} size="sm" onClick={() => onChange(alerts.filter((candidate) => candidate.id !== alert.id))}>
									<Trash2 aria-hidden="true" className="size-3.5" />
								</TooltipIconButton>
							)}
						</li>
					))}
				</ul>
			)}
			{readOnly || targets.length === 0 ? null : (
				<form
					className={cn('flex flex-wrap items-end gap-2 border-t pt-3', dashedRule)}
					onSubmit={(event) => {
						event.preventDefault();
						const id = `alert-${target}-${threshold}`;
						// One alert per target and threshold; adding it again just turns it back on.
						onChange(
							alerts.some((alert) => alert.id === id)
								? alerts.map((alert) => (alert.id === id ? { ...alert, enabled: true } : alert))
								: [...alerts, { id, target, kind: 'percent', threshold, enabled: true }],
						);
					}}
				>
					<label htmlFor={targetId} className="flex min-w-40 flex-1 flex-col gap-1 text-xs text-muted-foreground">
						Alert me about
						<select
							id={targetId}
							value={target}
							onChange={(event) => setTarget(event.target.value)}
							className={nativeSelectClass}
						>
							{targets.map((option) => (
								<option key={option.value} value={option.value}>
									{option.label}
								</option>
							))}
						</select>
					</label>
					<label htmlFor={thresholdId} className="flex w-24 flex-col gap-1 text-xs text-muted-foreground">
						At
						<span className="flex h-8 items-center rounded-md border border-border bg-card pe-2 shadow-2xs focus-within:ring-[3px] focus-within:ring-ring/50">
							<input
								id={thresholdId}
								type="number"
								min={1}
								max={100}
								value={threshold}
								onChange={(event) => setThreshold(Math.min(100, Math.max(1, Number(event.target.value) || 1)))}
								className="h-full w-full min-w-0 bg-transparent px-2 text-[0.8125rem] text-foreground tabular-nums outline-none"
							/>
							<span className="text-[0.8125rem] text-muted-foreground">%</span>
						</span>
					</label>
					<Button type="submit" size="sm" variant="outline">
						<Plus aria-hidden="true" />
						Add alert
					</Button>
				</form>
			)}
		</div>
	);
}

import { dateFormat, listFormat, numberFormat, pluralRules, relativeTimeFormat } from '@/lib/intl';
import type {
	BillingHealth,
	BillingInterval,
	BillingLifecycle,
	BillingOperationState,
	CreditGrantSource,
	CreditType,
	InvoiceStatus,
	LedgerEntryType,
	Money,
	ProviderStatus,
	ReadinessStatus,
	RedeemRefusal,
	SuspensionReason,
	SyncState,
} from '@/components/ui/billing-kit/types';

export type BillingFormatOptions = {
	locale: string;
	/** IANA zone used for every date, so server and client render the same text. */
	timeZone: string;
};

export const DEFAULT_FORMAT: BillingFormatOptions = { locale: 'en-US', timeZone: 'UTC' };

export type Tone = 'neutral' | 'success' | 'warning' | 'danger' | 'info' | 'primary';

export type Presentation = { label: string; tone: Tone; description?: string };

export const isUnlimited = (limit: number) => limit < 0;

// Cached Intl formatters, shared with the other kits.
export { dateFormat, numberFormat } from '@/lib/intl';

/** "a, b, and c" in the given locale. */
export function formatList(items: string[], locale: string) {
	return listFormat(locale).format(items);
}

/* ------------------------------------------------------------------ *
 * Numbers and money
 * ------------------------------------------------------------------ */

function fractionDigits(currency: string, locale: string) {
	try {
		return numberFormat(locale, { style: 'currency', currency }).resolvedOptions().maximumFractionDigits ?? 2;
	} catch {
		return 2;
	}
}

/**
 * Formats minor-unit money. Whole amounts drop their decimals (`$49`, not
 * `$49.00`) unless `precise` is set, which invoices and ledgers want.
 */
export function formatMoney(money: Money, options: BillingFormatOptions & { precise?: boolean; compact?: boolean }) {
	const currency = money.currency.toUpperCase();
	const digits = fractionDigits(currency, options.locale);
	const major = money.amountMinor / 10 ** digits;
	const whole = Number.isInteger(major);
	try {
		return numberFormat(options.locale, {
			style: 'currency',
			currency,
			notation: options.compact ? 'compact' : 'standard',
			minimumFractionDigits: options.compact ? 0 : options.precise || !whole ? digits : 0,
			maximumFractionDigits: options.compact ? 1 : digits,
		}).format(major);
	} catch {
		return `${currency} ${major.toFixed(digits)}`;
	}
}

/** Plain or compact count: `12,480` or `12.5K`. */
export function formatQuantity(value: number, options: Pick<BillingFormatOptions, 'locale'> & { compact?: boolean }) {
	return numberFormat(options.locale, {
		notation: options.compact ? 'compact' : 'standard',
		maximumFractionDigits: options.compact ? 1 : Number.isInteger(value) ? 0 : 2,
	}).format(value);
}

/**
 * A plan limit as a contract states it: exact with digit grouping below a
 * million (`12,345 GB`, never `12.3K GB`), compact only from there (`1.2M`).
 */
export function formatLimit(value: number, options: Pick<BillingFormatOptions, 'locale'>) {
	return formatQuantity(value, { locale: options.locale, compact: Math.abs(value) >= 1_000_000 });
}

/** Share of a limit used, or `null` when the limit is unlimited. Zero limits count as fully used once anything is used. */
export function usageRatio(used: number, limit: number): number | null {
	if (isUnlimited(limit)) return null;
	if (limit === 0) return used > 0 ? Infinity : 0;
	return used / limit;
}

export type UsageLevel = 'ok' | 'warning' | 'exhausted' | 'over';

/** Warning at the soft threshold (80% by default), exhausted at 100%, over past it. */
export function usageLevel(used: number, limit: number, soft = 0.8): UsageLevel {
	const ratio = usageRatio(used, limit);
	if (ratio === null) return 'ok';
	if (ratio > 1) return 'over';
	if (ratio >= 1) return 'exhausted';
	return ratio >= soft ? 'warning' : 'ok';
}

export function formatPercent(ratio: number, locale: string) {
	if (!Number.isFinite(ratio)) return '100%+';
	const digits = ratio < 0.1 && ratio > 0 ? 1 : 0;
	// A pool at 99.95% is not full: keep a ratio below 1 from rounding up to "100%".
	const shown = ratio < 1 && Math.round(ratio * 10 ** (2 + digits)) / 10 ** (2 + digits) >= 1 ? 0.99 : ratio;
	return numberFormat(locale, { style: 'percent', maximumFractionDigits: digits }).format(shown);
}

/* ------------------------------------------------------------------ *
 * Dates
 * ------------------------------------------------------------------ */

/**
 * `short` leaves the year out for dates in the current year (`Jan 1`) and adds
 * it for any other year (`Jan 1, 2027`), so a yearly period never reads
 * `Jan 1 - Jan 1`. Pass `now` to say which year is current. An unset (epoch
 * zero) timestamp renders as an em dash.
 */
export function formatDate(iso: string, options: BillingFormatOptions & { style?: 'short' | 'medium' | 'long'; withTime?: boolean; now?: string }) {
	const date = new Date(iso);
	if (Number.isNaN(date.getTime())) return iso;
	if (date.getTime() === 0) return '—';
	const style = options.style ?? 'medium';
	const otherYear = style === 'short' && options.now ? yearOf(iso, options.timeZone) !== yearOf(options.now, options.timeZone) : false;
	return dateFormat(options.locale, {
		timeZone: options.timeZone,
		month: style === 'long' ? 'long' : 'short',
		day: 'numeric',
		year: style === 'short' && !otherYear ? undefined : 'numeric',
		hour: options.withTime ? 'numeric' : undefined,
		minute: options.withTime ? '2-digit' : undefined,
	}).format(date);
}

function yearOf(iso: string, timeZone: string) {
	const date = new Date(iso);
	return Number.isNaN(date.getTime()) ? '' : dateFormat('en-US', { timeZone, year: 'numeric' }).format(date);
}

/** Clock time only, e.g. "2:12 PM". */
export function formatTime(iso: string, options: BillingFormatOptions) {
	return dateFormat(options.locale, { timeZone: options.timeZone, hour: 'numeric', minute: '2-digit' }).format(new Date(iso));
}

/** Calendar day in a time zone, as a sortable `YYYY-MM-DD` key. */
export function dayKey(iso: string, timeZone: string) {
	return dateFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso));
}

export const DAY = 86_400_000;

/**
 * Whether a readiness verdict still counts. `enable_billing` refuses to turn
 * on without a passing verdict from the last 24 hours.
 */
export function isHealthFresh(health: Pick<BillingHealth, 'checkedAt'>, now: string) {
	return health.checkedAt ? new Date(now).getTime() - new Date(health.checkedAt).getTime() < DAY : false;
}

/** Whole days from `now` to `iso`; negative in the past. */
export function daysUntil(iso: string, now: string) {
	return Math.round((new Date(iso).getTime() - new Date(now).getTime()) / DAY);
}

/**
 * Calendar days from `now` to `iso` in a time zone: 9 hours from now across
 * midnight is tomorrow, and 9 hours from now on the same date is today.
 */
export function calendarDaysUntil(iso: string, now: string, timeZone = 'UTC') {
	if (Number.isNaN(new Date(iso).getTime()) || Number.isNaN(new Date(now).getTime())) return NaN;
	return Math.round((Date.parse(`${dayKey(iso, timeZone)}T00:00:00Z`) - Date.parse(`${dayKey(now, timeZone)}T00:00:00Z`)) / DAY);
}

/** "in 3 days", "tomorrow", "2 days ago", counted in calendar days of the given time zone. */
export function formatRelativeDays(iso: string, now: string, locale: string, timeZone = 'UTC') {
	const days = calendarDaysUntil(iso, now, timeZone);
	if (!Number.isFinite(days)) return iso;
	return relativeTimeFormat(locale).format(days, 'day');
}

/** Share of the period elapsed at `now`, clamped to 0..1. */
export function periodProgress(start: string, end: string, now: string) {
	const from = new Date(start).getTime();
	const to = new Date(end).getTime();
	return Math.min(1, Math.max(0, (new Date(now).getTime() - from) / (to - from)));
}

