							{item.kind === 'refund' ? 'Refund' : 'Dispute'} · <span className="capitalize">{item.status.replace(/_/g, ' ')}</span>
						</span>
						<span className="block text-xs text-muted-foreground [overflow-wrap:anywhere]">
							{item.reason ? `${item.reason} · ` : ''}
