const METHOD_ICON: Record<PaymentMethodSummary['kind'], LucideIcon> = {
	card: CreditCard,
	bank_account: Landmark,
	wallet: Wallet,
	invoice: FileText,
	other: CircleDollarSign,
};

/** Whole months from `now` to a card's expiry month: negative once it has expired, 0 in its last month. */
function monthsToExpiry(method: PaymentMethodSummary, now: string) {
	if (!method.expMonth || !method.expYear) return null;
	const today = new Date(now);
	return (method.expYear - today.getUTCFullYear()) * 12 + (method.expMonth - (today.getUTCMonth() + 1));
}

/**
 * The payment method on file, whichever provider holds it: brand or scheme,
 * the last four digits, and a card's expiry, flagged when it has run out or
 * runs out next month.
 */
export function PaymentMethodRow({ method, className }: { method: PaymentMethodSummary; className?: string }) {
	const f = useBillingFormat();
	const months = monthsToExpiry(method, f.now);
	const expiry = months === null ? null : `${months < 0 ? 'Expired' : 'Expires'} ${String(method.expMonth).padStart(2, '0')}/${String(method.expYear).slice(-2)}`;
	return (
		<div className={cn('flex min-w-0 items-center gap-3', className)}>
			<IconTile icon={METHOD_ICON[method.kind]} tone={months !== null && months < 0 ? 'danger' : 'neutral'} />
			<span className="min-w-0 flex-1">
				<span title={method.label} className="block truncate text-[0.8125rem] text-foreground">
					{method.label}
					{method.last4 ? <span className="text-muted-foreground tabular-nums"> •••• {method.last4}</span> : null}
				</span>
				{method.detail || expiry ? (
					<span className={cn('block truncate text-xs tabular-nums', months !== null && months < 0 ? 'text-destructive' : 'text-muted-foreground')}>
						{[method.detail, expiry].filter(Boolean).join(' · ')}
					</span>
				) : null}
			</span>
			{months !== null && months >= 0 && months <= 1 ? <ToneBadge tone="warning">Expires soon</ToneBadge> : null}
		</div>
	);
}

'use client';

import { History } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { isUnsetDate } from '@/lib/intl';
import { dayKey, LEDGER_ENTRY } from '@/components/ui/billing-kit/format';
import { dashedRule, EmptyState, StatusBadge } from '@/components/ui/billing-kit/surface';
import type { LedgerEntry, Meter } from '@/components/ui/billing-kit/types';

const NEGATIVE_ENTRIES = new Set<LedgerEntry['entryType']>(['expired', 'reset', 'credits_consumed', 'credit_deduction']);

type LedgerTimelineProps = {
	entries: LedgerEntry[];
	meters: Meter[];
	/** The surface the timeline sits on, so the sticky day headings match it. */
	surface?: 'background' | 'card';
	className?: string;
};

/**
 * The append-only ledger, grouped by day: each entry's type, the meter it
 * touched, the change, and the running total after it. Grants read as
 * positive, expiries and pool draws as negative, and usage as a plain count.
 */
export function LedgerTimeline({ entries, meters, surface = 'background', className }: LedgerTimelineProps) {
	const f = useBillingFormat();
	// A zero timestamp is an unset value; it gets its own heading rather than "Jan 1, 1970".
	const dayHeading = (at: string) => (isUnsetDate(at) ? 'Undated' : f.date(at, 'long'));
	const meterBySlug = React.useMemo(() => new Map(meters.map((meter) => [meter.slug, meter])), [meters]);
	const groups = React.useMemo(() => {
		const byDay = new Map<string, LedgerEntry[]>();
		for (const entry of [...entries].sort((a, b) => b.at.localeCompare(a.at))) {
			const key = dayKey(entry.at, f.timeZone);
			const day = byDay.get(key);
			if (day) day.push(entry);
			else byDay.set(key, [entry]);
		}
		return [...byDay.entries()];
	}, [entries, f.timeZone]);

	if (entries.length === 0) {
		return <EmptyState icon={History} title="Nothing recorded yet" description="Usage, grants, resets, and expiries are logged here as they happen." className={className} />;
	}

	return (
		<div className={cn('flex flex-col gap-5', className)}>
			{groups.map(([day, list]) => (
				<section key={day} aria-label={dayHeading(list[0]!.at)}>
					<h3 className={cn('sticky top-0 z-10 py-1 text-xs text-muted-foreground backdrop-blur-sm', surface === 'card' ? 'bg-card/90' : 'bg-background/90')}>{dayHeading(list[0]!.at)}</h3>
					<ol className="mt-1 flex flex-col">
						{list.map((entry, index) => {
							const meter = meterBySlug.get(entry.meterSlug);
							const presentation = LEDGER_ENTRY[entry.entryType];
							const positive = entry.ledgerClass === 'grant' || entry.entryType === 'rollover';
							const sign = positive ? '+' : NEGATIVE_ENTRIES.has(entry.entryType) ? '−' : '';
							return (
								<li
									key={entry.id}
									className={cn(
										// Narrow: the time sits above the entry. Wide: it takes its own column. The middle column keeps a floor so a long amount cannot squeeze the meter name.
										'grid grid-cols-[minmax(8rem,1fr)_auto] items-baseline gap-x-3 gap-y-0.5 py-2 @md/view:grid-cols-[4.5rem_minmax(8rem,1fr)_auto]',
										index > 0 && cn('border-t', dashedRule),
									)}
								>
									<span className="col-span-2 text-xs text-subtle-foreground tabular-nums @md/view:col-span-1">{isUnsetDate(entry.at) ? '—' : f.time(entry.at)}</span>
									<span className="flex min-w-0 flex-col gap-1">
										<span className="flex flex-wrap items-center gap-2">
											<StatusBadge presentation={presentation} />
											<span className="line-clamp-2 min-w-0 text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">{meter?.displayName ?? entry.meterSlug}</span>
										</span>
										{entry.note ? <span className="text-xs text-muted-foreground [overflow-wrap:anywhere]">{entry.note}</span> : null}
									</span>
									<span className="flex flex-col items-end text-end text-[0.8125rem] tabular-nums [overflow-wrap:anywhere]">
										<span className={cn('font-medium', positive ? 'text-success' : entry.entryType === 'refused' ? 'text-destructive' : 'text-foreground')}>
											{sign}
											{f.quantity(Math.abs(entry.delta))}
											{entry.entryType === 'refused' ? <span className="sr-only"> refused</span> : null}
										</span>
										<span className="text-xs text-subtle-foreground">
											{f.quantity(entry.usageAfter, true)} {meter?.unit ?? ''}
										</span>
									</span>
								</li>
							);
						})}
					</ol>
				</section>
			))}
		</div>
	);
}

'use client';

import { ArrowDownRight, ArrowRight, ArrowUpRight, ExternalLink, TriangleAlert } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Dialog, DialogDescription, DialogFooter, DialogHeader, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { INTERVAL_PHRASE, isUnlimited, unitFor } from '@/components/ui/billing-kit/format';
import { type EntitlementRow, isPlanAvailable, priceFor, resolvePrice } from '@/components/ui/billing-kit/plan';
import { hasFeature, type BillingProviderDescriptor } from '@/components/ui/billing-kit/providers';
import { dashedRule } from '@/components/ui/billing-kit/surface';
import type { Balance, LimitCounter, Plan, PlanPrice, Subscription } from '@/components/ui/billing-kit/types';

export type PlanChangeTiming = 'now' | 'period_end';

export type PlanChangeRequest = {
	plan: Plan;
	price: PlanPrice | undefined;
	timing: PlanChangeTiming;
	/** True when the change has to go through the provider's hosted checkout. */
	checkout: boolean;
};

type PlanChangeDialogProps = {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	currentPlan?: Plan;
	targetPlan?: Plan;
	interval: 'month' | 'year';
	subscription?: Subscription;
	rows: EntitlementRow[];
	limits?: LimitCounter[];
	balances?: Balance[];
	provider?: BillingProviderDescriptor;
	/** Resolve to close the dialog; reject with an Error to show its message and stay open. */
	onConfirm: (request: PlanChangeRequest) => Promise<void> | void;
};

type Diff = { row: EntitlementRow; from: number | undefined; to: number | undefined; direction: 'up' | 'down' };

function valueOf(plan: Plan | undefined, row: EntitlementRow) {
	if (!plan) return undefined;
	return (row.kind === 'limit' ? plan.limits : row.kind === 'meter' ? plan.meterLimits : plan.caps)[row.key];
}

/** Orders values with unlimited (-1) above every finite number. */
const rank = (value: number | undefined) => (value === undefined ? 0 : isUnlimited(value) ? Infinity : value);

function diffPlans(from: Plan | undefined, to: Plan, rows: EntitlementRow[]): Diff[] {
	return rows.flatMap((row) => {
		const before = valueOf(from, row);
		const after = valueOf(to, row);
		if (rank(before) === rank(after)) return [];
		return [{ row, from: before, to: after, direction: rank(after) > rank(before) ? 'up' : 'down' } as Diff];
	});
}

/**
 * A move to a cheaper monthly price is a downgrade; with no prices to compare
 * (free to free, custom plans), the entitlement diff decides.
 */
function isDowngrade(from: Plan | undefined, to: Plan | undefined, diffs: Diff[]) {
	if (!from || !to) return false;
	const before = priceFor(from, 'month')?.amount.amountMinor;
	const after = priceFor(to, 'month')?.amount.amountMinor;
	if (before !== undefined && after !== undefined && before !== after) return after < before;
	const down = diffs.filter((diff) => diff.direction === 'down').length;
	return down > diffs.length - down;
}

function Value({ value, row }: { value: number | undefined; row: EntitlementRow }) {
	const f = useBillingFormat();
	if (value === undefined || value === 0) return <span className="text-subtle-foreground">{row.kind === 'cap' ? 'Off' : 'None'}</span>;
	if (row.kind === 'cap' && value === 1) return <>On</>;
	if (isUnlimited(value)) return <>Unlimited</>;
	return <>{f.limit(value)}</>;
}

/**
 * Previews a plan change before anything is sent: what goes up or down, what
 * the account already uses beyond the new plan, and when the change applies.
 * Upgrades default to now; downgrades default to the end of the period when
 * the provider can schedule changes.
 */
export function PlanChangeDialog({
	open,
	onOpenChange,
	currentPlan,
	targetPlan,
	interval,
	subscription,
	rows,
	limits = [],
	balances = [],
	provider,
	onConfirm,
}: PlanChangeDialogProps) {
	const f = useBillingFormat();
	const [timing, setTiming] = React.useState<PlanChangeTiming>('now');
	const [busy, setBusy] = React.useState(false);
	const [error, setError] = React.useState<string | null>(null);
	const timingId = React.useId();

	const diffs = React.useMemo(() => (targetPlan ? diffPlans(currentPlan, targetPlan, rows) : []), [currentPlan, rows, targetPlan]);
	const price = targetPlan ? resolvePrice(targetPlan, interval) : undefined;
	const downgrade = isDowngrade(currentPlan, targetPlan, diffs);
	const canSchedule = Boolean(subscription) && hasFeature(provider, 'scheduledChanges');
	const paid = Boolean(price && price.amount.amountMinor > 0);
	const checkout = paid && (!subscription || subscription.lifecycle === 'unsubscribed' || subscription.lifecycle === 'ended') && hasFeature(provider, 'hostedCheckout');

	// Each opening (or a new target) starts from its own default, set during render so the wrong timing never paints.
	const session = open ? (targetPlan?.id ?? '') : null;
	const [lastSession, setLastSession] = React.useState<string | null>(null);
	if (session !== lastSession) {
		setLastSession(session);
		if (session !== null) {
			setTiming(downgrade && canSchedule ? 'period_end' : 'now');
			setError(null);
			setBusy(false);
		}
	}

	const conflicts = React.useMemo(() => {
		if (!targetPlan) return { limits: [] as string[], meters: [] as string[] };
		const limitConflicts = limits.flatMap((limit) => {
			const max = targetPlan.limits[limit.name];
			return max !== undefined && !isUnlimited(max) && limit.used > max
				? [`${f.quantity(limit.used)} ${unitFor(limit.used, limit.unit, limit.unitSingular)} in use; ${targetPlan.displayName} allows ${f.quantity(max)}.`]
				: [];
		});
		const meterRows = new Map(rows.filter((row) => row.kind === 'meter').map((row) => [row.key, row]));
		const meterConflicts = balances.flatMap((balance) => {
			const max = targetPlan.meterLimits[balance.meterSlug];
			const row = meterRows.get(balance.meterSlug);
			return row && max !== undefined && !isUnlimited(max) && balance.currentUsage > max ? [row.label.toLowerCase()] : [];
		});
		return { limits: limitConflicts, meters: meterConflicts };
	}, [balances, f, limits, rows, targetPlan]);
	const meterNote =
		timing === 'now' && conflicts.meters.length > 0 && targetPlan
			? `This period is already past ${targetPlan.displayName}’s allowance for ${f.list(conflicts.meters)}, so the rest of the period draws from credits.`
			: null;

	if (!targetPlan) return null;
	// A plan whose prices were all retired cannot be started or switched to; it is not a free plan.
	if (!isPlanAvailable(targetPlan)) return <UnavailablePlanDialog open={open} onOpenChange={onOpenChange} plan={targetPlan} switching={Boolean(currentPlan)} />;

	const confirm = async () => {
		setBusy(true);
		setError(null);
		try {
			await onConfirm({ plan: targetPlan, price, timing, checkout });
			onOpenChange(false);
		} catch (reason) {
			setError(reason instanceof Error ? reason.message : 'The change could not be made. Try again.');
		} finally {
			setBusy(false);
		}
	};

	const periodEnd = subscription ? f.date(subscription.currentPeriodEnd) : null;

	return (
		<Dialog open={open} onOpenChange={(next) => (busy ? undefined : onOpenChange(next))}>
			<DialogPopup className="max-w-md">
				<DialogHeader className="gap-1.5 pb-3">
					<DialogTitle className="text-base font-medium">
						{currentPlan ? `${downgrade ? 'Switch' : 'Upgrade'} to ${targetPlan.displayName}` : `Start ${targetPlan.displayName}`}
					</DialogTitle>
					<DialogDescription className="text-[0.8125rem]">
						{price && paid
							? `${f.money(price.amount)} ${INTERVAL_PHRASE[price.interval]}${priceFor(targetPlan, price.interval, 'metered') ? ', plus usage past the allowance' : ''}.`
							: targetPlan.contactSales
								? 'Custom pricing.'
								: 'No charge.'}
					</DialogDescription>
				</DialogHeader>
				<div className="flex flex-col gap-4 px-6 pb-5">
					{diffs.length > 0 ? (
						<ul aria-label="What changes" className="flex flex-col rounded-lg border border-border px-3 py-1 text-[0.8125rem]">
							{diffs.map((diff, index) => (
								<li key={`${diff.row.kind}:${diff.row.key}`} className={cn('flex items-center gap-2 py-1.5', index > 0 && cn('border-t', dashedRule))}>
									{diff.direction === 'up' ? (
										<ArrowUpRight aria-hidden="true" className="size-3.5 shrink-0 text-success" />
									) : (
										<ArrowDownRight aria-hidden="true" className="size-3.5 shrink-0 text-warning" />
									)}
									<span title={diff.row.label} className="min-w-0 flex-1 truncate text-muted-foreground">
										{diff.row.label}
									</span>
									<span className="flex shrink-0 items-center gap-1.5 text-foreground tabular-nums">
										<span className="text-muted-foreground">
											<Value value={diff.from} row={diff.row} />
										</span>
										<ArrowRight aria-hidden="true" className="size-3 text-subtle-foreground rtl:-scale-x-100" />
										<span className="font-medium">
											<Value value={diff.to} row={diff.row} />
										</span>
										<span className="sr-only">{diff.direction === 'up' ? '(increase)' : '(decrease)'}</span>
									</span>
								</li>
							))}
						</ul>
					) : null}

					{conflicts.limits.length > 0 || meterNote ? (
						<div role="note" className="flex gap-2 rounded-lg bg-warning/10 px-3 py-2.5 text-[0.8125rem] text-foreground">
							<TriangleAlert aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-warning" />
							<div className="flex flex-col gap-1.5 text-pretty">
								{conflicts.limits.length > 0 ? (
									<>
										<ul className="flex flex-col gap-0.5">
											{conflicts.limits.map((conflict) => (
												<li key={conflict}>{conflict}</li>
											))}
										</ul>
										<p className="text-muted-foreground">Existing ones keep working, but new ones are refused until you are under the limit.</p>
									</>
								) : null}
								{meterNote ? <p className={conflicts.limits.length > 0 ? 'text-muted-foreground' : undefined}>{meterNote}</p> : null}
							</div>
						</div>
					) : null}

					{canSchedule && !checkout ? (
						<fieldset className="flex flex-col gap-2">
							<legend id={timingId} className="mb-2 text-xs text-muted-foreground">
								When should it apply?
							</legend>
							{(
								[
									{ value: 'now', title: 'Right away', detail: downgrade ? 'Unused time is credited to the next invoice.' : 'You pay the difference for the rest of this period.' },
									{ value: 'period_end', title: `At the end of the period${periodEnd ? `, ${periodEnd}` : ''}`, detail: 'Keep your current plan until then; cancel any time before.' },
								] as const
							).map((option) => (
								<label
									key={option.value}
									className={cn(
										'flex cursor-pointer items-start gap-2.5 rounded-lg border px-3 py-2.5 text-[0.8125rem] has-[:checked]:border-primary/40 has-[:checked]:bg-primary/[0.05]',
										'has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/50',
									)}
								>
									<input
										type="radio"
										name={timingId}
										value={option.value}
										checked={timing === option.value}
										onChange={() => setTiming(option.value)}
										className={cn('mt-0.5 accent-primary', focusRingClass)}
									/>
									<span className="min-w-0">
										<span className="block font-medium text-foreground">{option.title}</span>
										<span className="block text-muted-foreground">{option.detail}</span>
									</span>
								</label>
							))}
						</fieldset>
					) : null}

					{checkout ? (
						<p className="flex items-start gap-2 text-[0.8125rem] text-muted-foreground">
							<ExternalLink aria-hidden="true" className="mt-0.5 size-3.5 shrink-0" />
							You’ll finish payment on {provider?.name ?? 'the provider'}’s secure checkout. Nothing is charged until you confirm there.
						</p>
					) : null}

					{error ? (
						<p role="alert" className="text-[0.8125rem] text-destructive">
							{error}
						</p>
					) : null}
				</div>
				<DialogFooter>
					<Button variant="outline" size="sm" disabled={busy} onClick={() => onOpenChange(false)}>
						Cancel
					</Button>
					<Button size="sm" disabled={busy} aria-busy={busy || undefined} onClick={confirm}>
						{busy ? 'Working…' : checkout ? 'Continue to checkout' : timing === 'period_end' ? 'Schedule change' : downgrade ? 'Switch now' : 'Upgrade now'}
					</Button>
				</DialogFooter>
			</DialogPopup>
		</Dialog>
	);
}

/** What the dialog shows for a plan whose every price was retired: why it can't be chosen, and no way to confirm. */
function UnavailablePlanDialog({ open, onOpenChange, plan, switching }: { open: boolean; onOpenChange: (open: boolean) => void; plan: Plan; switching: boolean }) {
	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogPopup className="max-w-md">
				<DialogHeader className="gap-1.5 pb-3">
					<DialogTitle className="text-base font-medium">{switching ? `Switch to ${plan.displayName}` : `Start ${plan.displayName}`}</DialogTitle>
					<DialogDescription className="text-[0.8125rem]">No longer offered.</DialogDescription>
				</DialogHeader>
				<div className="px-6 pb-5">
					<div role="note" className="flex gap-2 rounded-lg bg-warning/10 px-3 py-2.5 text-[0.8125rem] text-foreground">
						<TriangleAlert aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-warning" />
						<p className="text-pretty [overflow-wrap:anywhere]">{plan.displayName} has no active price, so it can’t be started or switched to. Choose another plan.</p>
					</div>
				</div>
				<DialogFooter>
					<Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>
						Cancel
					</Button>
					<Button size="sm" disabled>
						Unavailable
					</Button>
				</DialogFooter>
			</DialogPopup>
		</Dialog>
	);
}

'use client';

import { Check, Minus, Sparkles, Tag } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Segmented, ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { PeriodTrack } from '@/components/ui/billing-kit/allowance';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { INTERVAL_SUFFIX, isUnlimited } from '@/components/ui/billing-kit/format';
import { LifecycleBadge } from '@/components/ui/billing-kit/status';
import { Bezel, dashedRule, EmptyState } from '@/components/ui/billing-kit/surface';
import type { BillingInterval, BillingLifecycle, Money, Plan, PlanPrice, Subscription } from '@/components/ui/billing-kit/types';

/* ------------------------------------------------------------------ *
 * Price helpers
 * ------------------------------------------------------------------ */

/** The active price for an interval and usage type. */
export function priceFor(plan: Plan, interval: BillingInterval, usageType: PlanPrice['usageType'] = 'licensed') {
	return plan.prices.find((price) => price.active && price.interval === interval && price.usageType === usageType);
}

/**
 * The price a plan is shown, previewed and started with for an interval: the
 * price for that interval, else the monthly one, else the yearly one, so a plan
 * sold for only one period still has a price. The card, the change preview and
 * the price handed to the host all read it from here, so they cannot disagree;
 * name the period from the result's own `interval`, not from the one asked for.
 */
export function resolvePrice(plan: Plan, interval: BillingInterval) {
	return priceFor(plan, interval) ?? priceFor(plan, 'month') ?? priceFor(plan, 'year');
}

/**
 * Whether a plan can be chosen right now: priced by sales, the free fallback, or
 * carrying at least one active price. A plan whose every price was retired is
 * not free, so it is neither offered nor started. A free tier modelled without
 * a price row has to be marked `fallback`, or it counts as retired and
 * `PlanComparison` hides it.
 */
export function isPlanAvailable(plan: Plan) {
	return Boolean(plan.contactSales || plan.fallback || plan.prices.some((price) => price.active));
}

/** Percent saved by paying yearly instead of twelve monthly payments, or null. */
export function yearlySavings(plan: Plan) {
	const monthly = priceFor(plan, 'month');
	const yearly = priceFor(plan, 'year');
	if (!monthly || !yearly || monthly.amount.amountMinor === 0) return null;
	const saved = 1 - yearly.amount.amountMinor / (monthly.amount.amountMinor * 12);
	return saved > 0.005 ? Math.round(saved * 100) : null;
}

/** The largest yearly saving across a catalog, for the interval switch. */
export function catalogSavings(plans: Plan[]) {
	return plans.reduce<number | null>((best, plan) => {
		const saved = yearlySavings(plan);
		return saved !== null && (best === null || saved > best) ? saved : best;
	}, null);
}

type PriceTagProps = {
	plan: Plan;
	interval: BillingInterval;
	/** A specific price to show, e.g. the one a subscription is on even after it was retired. Defaults to the plan's active price. */
	price?: PlanPrice;
	size?: 'md' | 'lg';
	/** Keeps the usage-note line even when empty, so side-by-side prices align. */
	reserveNote?: boolean;
	className?: string;
};

/**
 * "$49/mo", "Free", "Custom", or "Unavailable" for a plan whose prices were all
 * retired, with a quiet note when usage is billed on top.
 */
export function PriceTag({ plan, interval, price: priceOverride, size = 'md', reserveNote = false, className }: PriceTagProps) {
	const f = useBillingFormat();
	const price = priceOverride ?? resolvePrice(plan, interval);
	const metered = priceFor(plan, price?.interval ?? interval, 'metered');
	const big = size === 'lg' ? 'text-3xl' : 'text-2xl';
	const retired = !plan.contactSales && !priceOverride && !isPlanAvailable(plan);
	let figure: React.ReactNode;
	if (plan.contactSales) figure = <span className={cn(big, 'font-semibold tracking-tight')}>Custom</span>;
	else if (retired) figure = <span className={cn(big, 'font-semibold tracking-tight text-muted-foreground')}>Unavailable</span>;
	else if (!price || price.amount.amountMinor === 0) figure = <span className={cn(big, 'font-semibold tracking-tight')}>Free</span>;
	else {
		const perMonth = price.interval === 'year' && interval === 'year';
		const shown: Money = perMonth ? { ...price.amount, amountMinor: Math.round(price.amount.amountMinor / 12) } : price.amount;
		figure = (
			<>
				<span className={cn(big, 'font-semibold tracking-tight [overflow-wrap:anywhere]')}>{f.money(shown)}</span>
				<span className="text-[0.8125rem] whitespace-nowrap text-muted-foreground">{perMonth ? '/mo, billed yearly' : INTERVAL_SUFFIX[price.interval]}</span>
			</>
		);
	}
	return (
		<div className={cn('flex min-w-0 flex-col gap-0.5', className)}>
			<div className="flex flex-wrap items-baseline gap-x-1 text-foreground tabular-nums">{figure}</div>
			{retired ? (
				<span className="text-xs text-muted-foreground">No longer offered</span>
			) : metered && !plan.contactSales ? (
				<span className="text-xs text-muted-foreground">Plus usage past the allowance</span>
			) : reserveNote ? (
				<span aria-hidden="true" className="text-xs">
					&nbsp;
				</span>
			) : null}
		</div>
	);
}

type IntervalSwitchProps = {
	value: 'month' | 'year';
	onChange: (value: 'month' | 'year') => void;
	/** Best yearly saving, shown next to the switch. */
	savings?: number | null;
	className?: string;
};

export function IntervalSwitch({ value, onChange, savings, className }: IntervalSwitchProps) {
	return (
		<div className={cn('flex items-center gap-2', className)}>
			<Segmented
				label="Billing interval"
				value={value}
				onChange={onChange}
				options={[
					{ value: 'month', label: 'Monthly' },
					{ value: 'year', label: 'Yearly' },
				]}
			/>
			{savings ? <ToneBadge tone="success">Save up to {savings}%</ToneBadge> : null}
		</div>
	);
}

