	) : (
		<div className={cn(classes, soon && 'opacity-70')} aria-disabled={soon || undefined}>
			{body}
		</div>
	);
}

type ProviderConnectDialogProps = {
	providers: BillingProviderDescriptor[];
	/** The provider billing currently runs on, if any. */
	activeProviderId?: string;
	connection?: ProviderConnection;
	/** Opens straight on a provider's credentials step. */
	initialProviderId?: string;
	open: boolean;
	onOpenChange: (open: boolean) => void;
	/** Stores the credentials and makes the provider active. Reject with an Error to stay on the form. */
	onConnect: (providerId: string, values: Record<string, string>) => Promise<void> | void;
};

/**
 * Two steps: choose a provider, then enter its credentials. Choosing a
 * provider other than the active one explains the switch: new checkouts use
 * the new provider, existing subscriptions stay where they are until moved.
 */
export function ProviderConnectDialog({ providers, activeProviderId, connection, initialProviderId, open, onOpenChange, onConnect }: ProviderConnectDialogProps) {
	const [chosen, setChosen] = React.useState<string | undefined>(initialProviderId);
	// Reset to the requested step each time the dialog opens, during render so the old step never flashes.
	const [wasOpen, setWasOpen] = React.useState(open);
	if (open !== wasOpen) {
		setWasOpen(open);
		if (open) setChosen(initialProviderId);
	}
	const provider = providers.find((candidate) => candidate.id === chosen);
	const active = providers.find((candidate) => candidate.id === activeProviderId);
	const switching = Boolean(provider && active && provider.id !== active.id);
	const bodyRef = React.useRef<HTMLDivElement>(null);

	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogPopup
				className="max-w-lg"
				// Land on the first field or provider, not the back button, so its tooltip does not open on arrival.
				initialFocus={() => bodyRef.current?.querySelector<HTMLElement>('input, button') ?? true}
			>
				<ViewAnimation>
					<div key={provider?.id ?? 'pick'}>
						<DialogHeader className="gap-1.5 pb-3">
							<div className="flex items-center gap-2">
								{provider ? (
									<TooltipIconButton label="Back to providers" size="sm" onClick={() => startViewTransition(() => setChosen(undefined))}>
										<ArrowLeft aria-hidden="true" className="size-3.5 rtl:-scale-x-100" />
									</TooltipIconButton>
								) : null}
								<DialogTitle className="text-base font-medium">{provider ? `Connect ${provider.name}` : 'Choose a payment provider'}</DialogTitle>
							</div>
							<DialogDescription className="text-[0.8125rem]">
								{provider
									? 'Keys are stored as write-only secrets for this database and are never shown again.'
									: 'One provider handles checkout, subscriptions, and invoices at a time. You can switch later.'}
							</DialogDescription>
						</DialogHeader>
						<div ref={bodyRef} className="px-6 pb-6">
							{provider ? (
								<div className="flex flex-col gap-4">
									{switching ? (
										<div role="note" className="flex gap-2 rounded-lg bg-warning/10 px-3 py-2.5 text-[0.8125rem] text-foreground">
											<TriangleAlert aria-hidden="true" className="mt-0.5 size-3.5 shrink-0 text-warning" />
											<span className="text-pretty">
												New checkouts will use {provider.name}. Existing subscriptions stay on {active!.name} until each customer is moved, so keep{' '}
												{active!.name} connected until then.
											</span>
										</div>
									) : null}
									<ProviderCredentialForm
										provider={provider}
										connection={provider.id === connection?.providerId ? connection : undefined}
										submitLabel={switching ? `Switch to ${provider.name}` : `Connect ${provider.name}`}
										onSave={async (values) => {
											await onConnect(provider.id, values);
											onOpenChange(false);
										}}
									/>
								</div>
							) : (
								<ul className="flex flex-col gap-2">
									{providers.map((candidate) => (
										<li key={candidate.id}>
											<ProviderCard
												provider={candidate}
												connection={candidate.id === connection?.providerId ? connection : undefined}
												active={candidate.id === activeProviderId}
												onSelect={() => startViewTransition(() => setChosen(candidate.id))}
											/>
										</li>
									))}
								</ul>
							)}
						</div>
					</div>
				</ViewAnimation>
				{provider ? null : (
					<DialogFooter variant="bare" className="pt-0">
						<Button size="sm" variant="outline" onClick={() => onOpenChange(false)}>
							Close
						</Button>
					</DialogFooter>
				)}
			</DialogPopup>
		</Dialog>
	);
}

import { humanize } from '@/components/ui/billing-kit/format';
import type { ProviderMode } from '@/components/ui/billing-kit/types';

/**
 * What a payment provider can do. Components hide or explain an action when
 * the active provider lacks the feature, instead of assuming Stripe.
 */
export type ProviderFeature =
	| 'hostedCheckout'
	| 'customerPortal'
	| 'scheduledChanges'
	| 'meteredUsage'
	| 'invoices'
	| 'refunds'
	| 'disputes'
	| 'testMode';

export type ProviderCredentialField = {
	/** Secret or config name the host stores it under, e.g. `STRIPE_SECRET_KEY`. */
	name: string;
	label: string;
	/** Secrets are write-only: the UI shows whether one is set, never its value. */
	kind: 'secret' | 'config';
	placeholder?: string;
	help?: string;
	/** Expected prefix, checked before the host is called (e.g. `sk_`). */
	prefix?: string | string[];
	optional?: boolean;
};

export type ProviderObjectKind = 'account' | 'customer' | 'subscription' | 'invoice' | 'price' | 'product';

export type ProviderCheckCopy = { label: string; help?: string };

export type BillingProviderDescriptor = {
	id: string;
	name: string;
	description: string;
	/** Tile colour for the mark. */
	brandColor: string;
	/** One or two letters drawn on the tile when there is no `logo`. */
	monogram: string;
	/** Image URL or data URI drawn on the tile instead of the monogram; a white glyph reads best. */
	logo?: string;
	availability: 'available' | 'coming_soon';
	features: readonly ProviderFeature[];
	/**
	 * The provider sells to your customers in its own name (Paddle, Lemon
	 * Squeezy): it charges them, handles sales tax, and issues the invoices.
	 */
	merchantOfRecord?: boolean;
	/** Prices cannot be edited once the provider has them; the catalog says to add a new one instead. */
	immutablePrices?: boolean;
	/** What the provider calls its two modes, e.g. `{ test: 'Sandbox', live: 'Live' }`. Defaults to Test and Live. */
	modeLabels?: Readonly<Record<ProviderMode, string>>;
	/** Reads test or live off the credentials being saved, when the provider encodes it there. */
	detectMode?: (values: Readonly<Record<string, string>>) => ProviderMode | null;
	credentials: readonly ProviderCredentialField[];
	/** Copy for provider-specific readiness checks, keyed by check id. */
	checks?: Readonly<Record<string, ProviderCheckCopy>>;
	/** Deep link into the provider's own dashboard. */
	dashboardUrl?: (kind: ProviderObjectKind, id: string, mode: ProviderMode) => string | undefined;
	docsUrl?: string;
};

/** Readiness checks every provider shares, in the order the checklist shows them. */
export const PLATFORM_CHECKS: Readonly<Record<string, ProviderCheckCopy>> = {
	plan_catalog: { label: 'Plan catalog', help: 'At least one active plan has an active price.' },
	provider_mappings: { label: 'Catalog mirrored', help: 'Every active plan and price has a provider id.' },
	webhook_route: { label: 'Webhook endpoint', help: 'An inbound route receives provider events for this database.' },
	webhook_signing_secret: { label: 'Webhook signing secret', help: 'Deliveries are verified before anything is recorded.' },
	schedules: { label: 'Scheduled jobs', help: 'Usage sync, the overdue sweep, and the daily check are registered.' },
	billing_flag: { label: 'Billing switch', help: 'Billing stays off until you turn it on below.' },
};

const STRIPE_DASHBOARD = 'https://dashboard.stripe.com';

const STRIPE_PATHS: Record<ProviderObjectKind, string> = {
	account: 'settings/account',
	customer: 'customers',
	subscription: 'subscriptions',
	invoice: 'invoices',
	price: 'prices',
	product: 'products',
};

/** Built-in Stripe descriptor, matching what the Constructive billing functions implement today. */
export const STRIPE_PROVIDER: BillingProviderDescriptor = {
	id: 'stripe',
	name: 'Stripe',
	description: 'Hosted checkout, customer portal, subscription schedules, and usage-based billing on one credits meter.',
	brandColor: '#635bff',
	monogram: 'S',
	availability: 'available',
	features: ['hostedCheckout', 'customerPortal', 'scheduledChanges', 'meteredUsage', 'invoices', 'refunds', 'disputes', 'testMode'],
	immutablePrices: true,
	detectMode: (values) => (values.STRIPE_SECRET_KEY ? modeFromCredential(values.STRIPE_SECRET_KEY) : null),
	credentials: [
		{
			name: 'STRIPE_SECRET_KEY',
			label: 'Secret key',
			kind: 'secret',
			placeholder: 'sk_test_…',
			prefix: ['sk_test_', 'sk_live_', 'rk_test_', 'rk_live_'],
			help: 'A secret or restricted key. The mode follows the key prefix.',
		},
		{
			name: 'STRIPE_WEBHOOK_SECRET',
			label: 'Webhook signing secret',
			kind: 'secret',
			placeholder: 'whsec_…',
			prefix: 'whsec_',
			help: 'Shown on the webhook endpoint in your Stripe dashboard.',
		},
		{
			name: 'BILLING_PORTAL_RETURN_URL',
			label: 'Portal return URL',
			kind: 'config',
			placeholder: 'https://app.example.com/billing',
			optional: true,
		},
	],
	checks: {
		stripe_secret: { label: 'Secret key', help: 'A secret key is stored for this database.' },
		stripe_account: { label: 'Account reachable', help: 'The key opens the expected Stripe account.' },
		stripe_mode: { label: 'Mode matches', help: 'Test keys in test mode, live keys in live mode.' },
	},
	dashboardUrl: (kind, id, mode) =>
		`${STRIPE_DASHBOARD}${mode === 'test' ? '/test' : ''}/${STRIPE_PATHS[kind]}${kind === 'account' ? '' : `/${encodeURIComponent(id)}`}`,
};

export function hasFeature(provider: BillingProviderDescriptor | undefined, feature: ProviderFeature) {
	return Boolean(provider?.features.includes(feature));
}

/** Copy for a readiness check: the provider's own first, then the shared set, then the raw id. */
export function checkCopy(provider: BillingProviderDescriptor | undefined, id: string): ProviderCheckCopy {
	return provider?.checks?.[id] ?? PLATFORM_CHECKS[id] ?? { label: humanize(id) };
}

/** Validates a credential against its declared prefix before anything is sent. */
export function credentialError(field: ProviderCredentialField, value: string): string | null {
	const trimmed = value.trim();
	if (!trimmed) return field.optional ? null : `Enter the ${field.label.toLowerCase()}.`;
	const prefixes = field.prefix === undefined ? [] : Array.isArray(field.prefix) ? field.prefix : [field.prefix];
	if (prefixes.length > 0 && !prefixes.some((prefix) => trimmed.startsWith(prefix))) {
		return `Expected a value starting with ${prefixes.map((prefix) => `“${prefix}”`).join(' or ')}.`;
	}
	return null;
}

/** What the provider calls a mode: "Sandbox" for some, "Test" or "Live" by default. */
export function modeLabel(provider: BillingProviderDescriptor | undefined, mode: ProviderMode) {
	return provider?.modeLabels?.[mode] ?? (mode === 'live' ? 'Live' : 'Test');
}

/** Test or live, read off a Stripe-style key prefix (`sk_test_…`, `rk_live_…`). */
export function modeFromCredential(value: string): ProviderMode | null {
	if (/_test_/.test(value)) return 'test';
	if (/_live_/.test(value)) return 'live';
	return null;
}

'use client';

import { Database, ShieldCheck } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { ToneBadge } from '@/components/ui/workspace-kit/primitives';
import { useBillingFormat } from '@/components/ui/billing-kit/context';
import { SUSPENSION_REASON } from '@/components/ui/billing-kit/format';
import { EmptyState, StatusBadge, TableSurface, tableHeadClass, tableRowClass } from '@/components/ui/billing-kit/surface';
import type { DatabaseStanding } from '@/components/ui/billing-kit/types';

type StandingTableProps = {
	databases: DatabaseStanding[];
	/** Places an admin hold. The host confirms and calls `suspend_database(id, 'admin')`. */
	onHold?: (database: DatabaseStanding) => void;
	/** Lifts whatever suspension is present. The host calls `unsuspend_database(id)`. */
	onRelease?: (database: DatabaseStanding) => void;
	/** Database waiting on a host call. */
	pendingId?: string;
	className?: string;
};

/**
 * Database standing for platform operators. Billing suspensions lift on their
 * own once the owner has capacity again; admin holds outrank them and only an
 * operator can lift one.
 */
export function StandingTable({ databases, onHold, onRelease, pendingId, className }: StandingTableProps) {
	const f = useBillingFormat();
	if (databases.length === 0) {
		return <EmptyState icon={ShieldCheck} title="Everything is serving" description="No database is suspended or on hold." className={className} />;
	}
	return (
		<TableSurface className={className} minWidth="42rem">
					<thead className={tableHeadClass}>
						<tr>
							<th scope="col">Database</th>
							<th scope="col">Owner</th>
							<th scope="col">Standing</th>
							<th scope="col">Since</th>
							<th scope="col">
								<span className="sr-only">Actions</span>
							</th>
						</tr>
					</thead>
					<tbody>
						{databases.map((database) => {
							const reason = database.suspendedReason;
							const busy = pendingId === database.id;
							return (
								<tr key={database.id} className={tableRowClass}>
									<td>
										<span className="flex items-center gap-2.5">
											<Database aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
											<span className="min-w-0 max-w-[18rem]">
												<span title={database.name} className="line-clamp-2 block font-medium text-foreground [overflow-wrap:anywhere]">
													<bdi>{database.name}</bdi>
												</span>
												<span title={database.region ?? database.id} className="block truncate text-xs text-muted-foreground">
													{database.region ?? database.id}
												</span>
											</span>
										</span>
									</td>
									<td className="max-w-[14rem] text-muted-foreground [overflow-wrap:anywhere]">
										<bdi>{database.ownerName ?? '—'}</bdi>
									</td>
									<td>
										{reason ? (
											<span className="flex flex-col items-start gap-1">
												<StatusBadge presentation={SUSPENSION_REASON[reason]} />
												{database.note ? (
													<span title={database.note} className="line-clamp-3 max-w-[16rem] text-xs text-muted-foreground [overflow-wrap:anywhere]">
														{database.note}
													</span>
												) : null}
											</span>
										) : (
											<ToneBadge tone="success">Serving</ToneBadge>
										)}
									</td>
									<td className="whitespace-nowrap text-muted-foreground tabular-nums">{database.suspendedAt ? f.date(database.suspendedAt, 'medium', true) : '—'}</td>
									<td className="text-end whitespace-nowrap">
										{reason && onRelease ? (
											<Button size="xs" variant="outline" disabled={busy} aria-busy={busy || undefined} onClick={() => onRelease(database)}>
												{busy ? 'Releasing…' : reason === 'admin' ? 'Lift hold' : 'Restore'}
											</Button>
										) : null}
										{reason !== 'admin' && onHold ? (
											<Button size="xs" variant="destructive-outline" className="ms-2" disabled={busy} onClick={() => onHold(database)}>
												Hold
											</Button>
										) : null}
									</td>
								</tr>
							);
						})}
					</tbody>
		</TableSurface>
	);
}

