				{description ? <div className="mt-0.5 text-pretty text-[0.8125rem] text-muted-foreground [overflow-wrap:anywhere]">{description}</div> : null}
			</div>
			{actions ? <div className="flex shrink-0 flex-wrap items-center gap-2 self-center">{actions}</div> : null}
		</div>
	);
}

type BillingStatusBannerProps = {
	lifecycle: BillingLifecycle;
	subscription?: Subscription;
	/** Display name for a plan id, used by the scheduled-change notice. */
	planName?: (planId: string) => string;
	/** Databases this account owns; suspended ones are listed in the notice. */
	databases?: DatabaseStanding[];
	/** Renders the next step for the state, e.g. "Update payment method". */
	renderActions?: (state: BannerState) => React.ReactNode;
	className?: string;
};

export type BannerState = 'grace' | 'suspended' | 'checkout_pending' | 'review_required' | 'scheduled_change' | 'admin_hold' | 'unsubscribed' | 'ended';

/**
 * The one notice an account needs right now, in priority order: an admin
 * hold, a billing suspension, the grace period, a checkout still settling, a
 * provider change awaiting review, then a scheduled plan change. Renders
 * nothing when the account is in good standing.
 */
export function BillingStatusBanner({ lifecycle, subscription, planName, databases = [], renderActions, className }: BillingStatusBannerProps) {
	const f = useBillingFormat();
	const held = databases.filter((database) => database.suspendedReason === 'admin');
	const suspended = databases.filter((database) => database.suspendedReason === 'billing');
	const names = (list: DatabaseStanding[]) => nameList(list.map((database) => database.name), { locale: f.locale });

	let state: BannerState | null = null;
	let notice: Omit<NoticeProps, 'actions'> | null = null;

	if (held.length > 0) {
		state = 'admin_hold';
		notice = {
			tone: 'danger',
			icon: ShieldAlert,
			role: 'alert',
			title: held.length === 1 ? `${held[0]!.name} is on hold` : `${held.length} databases are on hold`,
			description: `A platform admin paused ${held.length === 1 ? 'this database' : names(held)}. Contact support to lift the hold.`,
		};
	} else if (lifecycle === 'suspended' || suspended.length > 0) {
		state = 'suspended';
		notice = {
			tone: 'danger',
			icon: OctagonAlert,
			role: 'alert',
			title: 'Billing suspended',
			description: (
				<>
					The grace period ended with no capacity left{suspended.length > 0 ? `, so ${names(suspended)} stopped serving requests` : ''}. Paying the open
					invoice, changing plan, or adding credits restores service right away.
				</>
			),
		};
	} else if (lifecycle === 'grace') {
		state = 'grace';
		const deadline = subscription?.graceDeadlineAt;
		notice = {
			tone: 'warning',
			icon: Hourglass,
			title: 'Payment failed',
			description: deadline ? (
				<>
					Service continues until <span className="font-medium text-foreground tabular-nums">{f.date(deadline)}</span> ({f.relative(deadline)}). Update the
					payment method to avoid a suspension.
				</>
			) : (
				'Service continues through the grace period. Update the payment method to avoid a suspension.'
			),
		};
	} else if (lifecycle === 'checkout_pending') {
		state = 'checkout_pending';
		notice = {
			tone: 'info',
			icon: CreditCard,
			title: <TextShimmer className="font-medium">Confirming your payment</TextShimmer>,
			description: 'The provider is settling the checkout. Your new plan applies as soon as it confirms; this usually takes a few seconds.',
		};
	} else if (lifecycle === 'review_required') {
		state = 'review_required';
		notice = {
			tone: 'warning',
			icon: CircleAlert,
			title: 'A billing change needs review',
			description: 'A provider update could not be confirmed. Nothing was charged twice; support will reconcile it and let you know.',
		};
	} else if (subscription?.scheduledChange) {
		state = 'scheduled_change';
		const change = subscription.scheduledChange;
		notice = {
			tone: 'info',
			icon: CalendarClock,
			title: `Moving to ${planName?.(change.planId) ?? change.planId} on ${f.date(change.effectiveAt)}`,
			description:
				change.state === 'preparing'
					? 'Scheduling the change with the provider.'
					: 'You keep everything in your current plan until then. Cancel the change any time before it takes effect.',
		};
	} else if (lifecycle === 'unsubscribed' || lifecycle === 'ended') {
		state = lifecycle;
		notice = {
			tone: 'neutral',
			icon: CreditCard,
			title: lifecycle === 'ended' ? 'Your subscription ended' : 'No plan yet',
			description: 'Pick a plan for higher limits and more included usage.',
		};
	}

	if (!state || !notice) return null;
	return <Notice {...notice} actions={renderActions?.(state)} className={className} />;
}

/**
 * Billing contracts shared by the Constructive billing templates.
 *
 * The vocabulary follows the Constructive billing modules: plans with licensed
 * and metered prices, meters grouped into category pools that fall back to a
 * universal credit pool, balances, credit grants, credit packs and codes,
 * limits and feature caps, the append-only ledger, the provider lifecycle, and
 * database standing. Hosts map their GraphQL (or any API) into these shapes;
 * nothing here knows about a provider SDK, a router, or a session store.
 *
 * Conventions:
 * - Money is an integer in the currency's smallest unit (`amountMinor`).
 * - A limit of `-1` means unlimited, as in the database.
 * - Timestamps are ISO 8601 strings; dates render in the host's time zone.
 */

/** Which billing plane a workspace shows: Constructive's own, or a tenant app's. */
export type BillingScope = 'platform' | 'tenant';

export type Money = {
	amountMinor: number;
	/** ISO 4217 code, lower or upper case. */
	currency: string;
};

/* ------------------------------------------------------------------ *
 * Catalog
 * ------------------------------------------------------------------ */

export type BillingInterval = 'month' | 'year' | 'one_time';

/** `licensed` is a flat amount per interval; `metered` bills burned credits as overage. */
export type UsageType = 'licensed' | 'metered';

export type PlanPrice = {
	id: string;
	interval: BillingInterval;
	usageType: UsageType;
	/** Metered prices carry 0: the per-credit charge derives from the credit rate. */
	amount: Money;
	discountPercent?: number;
	active: boolean;
	/** The provider's price id once the catalog has synced. */
	externalId?: string;
	syncState?: SyncState;
};

export type Plan = {
	id: string;
	/** Stable slug, e.g. `pro`. */
	name: string;
	displayName: string;
	description?: string;
	prices: PlanPrice[];
	/** Billing quota per meter slug (`plan_meter_limits`). */
	meterLimits: Record<string, number>;
	/** Feature caps (`plan_caps`): 0 off, 1 on, above 1 a numeric setting. */
	caps: Record<string, number>;
	/** Counted limits (`plan_limits`), e.g. databases or seats. */
	limits: Record<string, number>;
	/** Short selling points shown in comparisons. */
	highlights?: string[];
	recommended?: boolean;
	/** Priced by sales rather than checkout. */
	contactSales?: boolean;
	active: boolean;
	/**
	 * The free fallback plan an overdue subscription is downgraded to. A plan with
	 * no price rows counts as retired and is hidden from `PlanComparison` unless it
	 * is `fallback` (or `contactSales`), so a free tier without a price row sets it.
	 */
	fallback?: boolean;
	externalId?: string;
	syncState?: SyncState;
};

export type MeterType = 'quota' | 'boolean' | 'usage_pool';
export type MeterAggregation = 'cumulative' | 'peak';

export type Meter = {
	slug: string;
	displayName: string;
	/** Plural unit label, e.g. `operations`, `gigabytes`, `credits`. */
	unit: string;
	/** Label for a count of one, e.g. `operation`. Derived from `unit` when omitted; set it for irregular units. */
	unitSingular?: string;
	meterType: MeterType;
	aggregation: MeterAggregation;
	/** Universal credits per unit when the meter's own quota runs out. `null` disables the fallback. */
	creditCost: number | null;
	/** Parent pool in the waterfall; `null` falls straight through to `universal`. */
	categoryMeter: string | null;
	periodInterval: 'month' | 'year' | null;
	rolloverCap?: number | null;
	description?: string;
	active: boolean;
};

export type CreditType = 'permanent' | 'period' | 'rollover';

export type CreditPack = {
	id: string;
	slug: string;
	displayName: string;
	description?: string;
	/** Credits granted. */
	amount: number;
	meterSlug: string;
	creditType: CreditType;
	/** Advertised price; the charge derives from `credits_per_cent`. */
	price: Money;
	expiresAfterDays?: number;
	active: boolean;
	featured?: boolean;
};

/**
 * What a code item credits: a billing meter (`meter_credits`, e.g. the
 * compute pool) or a counted limit (`limit_credits`, e.g. seats). Limits
 * only take `permanent` or `period` credits.
 */
export type CreditTarget = { kind: 'meter' | 'limit'; key: string };

export type CreditCodeItem = {
	target: CreditTarget;
	amount: number;
	creditType: CreditType;
	/** Days the granted credits last after redemption; absent means they keep. */
	expiresAfterDays?: number;
};

export type CreditCode = {
	id: string;
	/** Case-insensitive and unique; shown upper-case. */
	code: string;
	items: CreditCodeItem[];
	/** `null` means unlimited. Each billing account can redeem a code once. */
	maxRedemptions: number | null;
	redemptions: number;
	expiresAt?: string;
	/** Admin toggle; a paused code refuses redemptions without being deleted. */
	active: boolean;
	/** Internal note, e.g. the campaign it belongs to. */
	note?: string;
	/** Codes created together by a bulk run share a batch. */
	batch?: string;
	createdAt?: string;
};

/** What an operator submits to create or edit a code. */
export type CreditCodeDraft = Pick<CreditCode, 'code' | 'items' | 'maxRedemptions' | 'expiresAt' | 'active' | 'note' | 'batch'>;

/** One billing account redeeming one code. */
export type CodeRedemption = {
	id: string;
	codeId: string;
	code: string;
	accountId: string;
	accountName?: string;
	redeemedAt: string;
	/** What the redemption granted, with each grant's expiry resolved. */
	items: (CreditCodeItem & { expiresAt?: string })[];
};

export type RedeemRefusal = 'not_found' | 'inactive' | 'expired' | 'exhausted' | 'already_redeemed' | 'not_eligible';

/**
 * The host's answer to a redemption. A refusal carries the reason (and an
 * optional message to show instead of the standard copy).
 */
export type RedeemResult = { status: 'redeemed'; redemption: CodeRedemption } | { status: 'refused'; reason: RedeemRefusal; message?: string };

/* ------------------------------------------------------------------ *
 * An account's state
 * ------------------------------------------------------------------ */

export type Balance = {
	meterSlug: string;
	currentUsage: number;
	/** From the plan; negative means unlimited. */
	planLimit: number;
	/** Credits applied on top of the plan (period, rollover and permanent). */
	purchasedCredits: number;
	/** `planLimit + purchasedCredits`; negative means unlimited. */
	effectiveLimit: number;
	periodCredits: number;
	rolloverCredits: number;
	nextExpiresAt?: string;
	/** Daily usage for the current period, oldest first. */
	daily?: number[];
	/** Credits this meter drew from its pool or the universal pool this period. */
	fallbackCredits?: number;
};

export type CreditGrantSource = 'plan' | 'purchase' | 'code' | 'admin' | 'rollover' | 'refund';

export type CreditGrant = {
	id: string;
	meterSlug: string;
	amount: number;
	/** Unconsumed part; equals `amount` until drawn down. */
	remaining: number;
	creditType: CreditType;
	source: CreditGrantSource;
