export type LedgerClass = 'usage' | 'grant' | 'adjustment' | 'refund';

export type LedgerEntryType =
	| 'increment'
	| 'decrement'
	| 'credit_purchase'
	| 'plan_grant'
	| 'reset'
	| 'adjustment'
	| 'credit_deduction'
	| 'credits_consumed'
	| 'expired'
	| 'rollover'
