/** A counted limit such as databases, seats, or organizations. */
export type LimitCounter = {
	name: string;
	label: string;
	used: number;
	/** `-1` means unlimited. */
	max: number;
	/** Non-blocking warning threshold. */
	softMax?: number;
	unit: string;
	/** Label for a count of one, e.g. `seat`. Derived from `unit` when omitted. */
	unitSingular?: string;
