/** A feature cap resolved for the account: 0 off, 1 on, above 1 a numeric setting. */
export type FeatureCap = {
	name: string;
	label: string;
	description?: string;
	value: number;
	kind: 'switch' | 'number';
	unit?: string;
	/** Label for a count of one, e.g. `day`. Derived from `unit` when omitted. */
	unitSingular?: string;
};

export type UsageAlert = {
	id: string;
	/** A meter slug or a limit name. */
	target: string;
	kind: 'percent' | 'absolute';
	threshold: number;
	enabled: boolean;
};

